<?php
namespace RoutesPro\Front;

class ClientPortalShortcodeRenderer {
    public static function client_portal($atts = []) {
        $guard = \RoutesPro\Shortcodes::front_guard();
        if ($guard) return $guard;
        if (class_exists('\\RoutesPro\\PWA\\InstallPrompt')) { \RoutesPro\PWA\InstallPrompt::markClientRendered(); }
        global $wpdb;
        $px = $wpdb->prefix . 'routespro_';
        $client_id = absint($atts['client_id'] ?? ($_GET['client_id'] ?? 0));
        $project_id = absint($atts['project_id'] ?? ($_GET['project_id'] ?? 0));
        [$client_id, $project_id] = \RoutesPro\Support\Permissions::resolve_front_context($client_id, $project_id);
        $theme = \RoutesPro\Shortcodes::front_theme($client_id, $project_id);
        $theme_classes = \RoutesPro\Support\Theme::root_classes($theme);
        $theme_style = \RoutesPro\Support\Theme::inline_style($theme);
        $theme_payload = \RoutesPro\Support\Theme::js_payload($theme);
        $global_theme_payload = \RoutesPro\Support\Theme::js_payload(\RoutesPro\Support\Theme::resolve(0, 0));
        $theme_map = \RoutesPro\Support\Theme::campaign_theme_map();
        $campaign_logo = (string)($theme['logo_url'] ?? '');
        $ui_composition_enabled = (bool)apply_filters('fieldflow_ui_composition_enabled', true, 'client');
        $paint_stability_enabled = (bool)apply_filters('fieldflow_portal_paint_stability_enabled', true, 'client');
        $nonce = wp_create_nonce('wp_rest');
        $export_nonce = wp_create_nonce('routespro_export_submissions');
        $dashboard_export_nonce = wp_create_nonce('routespro_export_dashboard');
        $route_export_nonce = wp_create_nonce('routespro_export_client_routes');
        $can_manage = current_user_can('routespro_manage');
        $can_scope = \RoutesPro\Support\Permissions::can_access_front();
        $clients = \RoutesPro\Support\Permissions::filter_clients($wpdb->get_results("SELECT id,name FROM {$px}clients ORDER BY name ASC", ARRAY_A) ?: []);
        $projects = \RoutesPro\Support\Permissions::filter_projects($wpdb->get_results("SELECT id,name,client_id FROM {$px}projects ORDER BY name ASC", ARRAY_A) ?: []);
        $saas_has = static function(string $capability) use ($client_id): bool {
            if (!class_exists('\RoutesPro\SaaS\EntitlementService')) return true;
            return $client_id > 0
                ? \RoutesPro\SaaS\EntitlementService::clientHas($client_id, $capability)
                : \RoutesPro\SaaS\EntitlementService::userHasAny($capability);
        };
        $allow_routes = $saas_has('routes.view');
        $allow_campaign_pdvs = $saas_has('campaign_pdvs.manage');
        $allow_reports = $saas_has('reporting.view');
        $allow_commercial = $saas_has('commercial.view');
        $allow_briefings = $saas_has('briefings.view');
        $allow_implementations = $saas_has('implementations.view');
        $allow_stocks = $saas_has('stocks.view');
        $allow_shopping_results = $saas_has('reporting.view');
        $allow_team = $saas_has('team.view');
        $allow_performance = $saas_has('growth_hub.view');
        $allow_analytics = $saas_has('analytics.basic');
        $allow_ai = $saas_has('ai.use');
        $allow_export_csv = $saas_has('exports.csv');
        $allow_export_excel = $saas_has('exports.excel');
        $allow_export_pdf = $saas_has('exports.pdf');
        ob_start(); ?>
