  async function syncOwners(){ if(!els.owner) return; const current=els.owner.value||''; const url=new URL(ownerAjaxUrl, window.location.origin); url.searchParams.set('action','routespro_project_operatives'); if(els.client&&els.client.value) url.searchParams.set('client_id',els.client.value); if(els.project&&els.project.value) url.searchParams.set('project_id',els.project.value); let users=[]; try{ const res=await fetch(url.toString(),{credentials:'same-origin'}); users=await res.json().catch(()=>[]); }catch(_){ users=[]; } users=Array.isArray(users)?users:[]; els.owner.innerHTML='<option value="">Operativo</option>'+users.map(u=>`<option value="${parseInt(u.ID||0,10)}">${esc(u.label||u.display_name||('#'+(u.ID||'')))}</option>`).join(''); if(current && Array.from(els.owner.options).some(o=>String(o.value)===String(current))) els.owner.value=current; }
  function locationOptions(){ return Array.from(els.location?.options||[]).filter(o=>String(o.value||'')!==''); }
  function normalizeLocationText(value){ return String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim(); }
  function locationSearchQuery(){ return normalizeLocationText(els.locationSearch?.value||''); }
  function placeLocationPicker(){ if(!els.locationPicker||!els.locationOptions||!els.locationSearch) return; const r=els.locationSearch.getBoundingClientRect(); const margin=10; const width=Math.max(240, r.width); els.locationOptions.style.left=Math.max(margin, Math.round(r.left))+'px'; els.locationOptions.style.top=Math.round(r.bottom+6)+'px'; els.locationOptions.style.width=Math.min(width, window.innerWidth-(margin*2))+'px'; els.locationOptions.style.maxHeight=Math.max(180, Math.min(360, window.innerHeight-r.bottom-24))+'px'; }
  function openLocationPicker(open=true){ if(!els.locationPicker) return; els.locationPicker.classList.toggle('open', !!open); if(els.locationSearch) els.locationSearch.setAttribute('aria-expanded', open?'true':'false'); if(open){ renderLocationOptions(); requestAnimationFrame(placeLocationPicker); } }
  function syncLocationSearchText(){ if(!els.location||!els.locationSearch) return; const opt=locationOptions().find(o=>String(o.value||'')===String(els.location.value||'')); if(document.activeElement!==els.locationSearch){ els.locationSearch.value=(opt&&opt.value)?opt.text:''; } if(els.locationPicker) els.locationPicker.classList.toggle('has-value', !!(opt&&opt.value)); }
  function chooseLocation(value, label){ if(!els.location) return; els.location.value=String(value||''); if(els.locationSearch) els.locationSearch.value=label||''; syncLocationSearchText(); openLocationPicker(false); state.selectedRouteId=0; state.selectedRoute=null; state.routeListPage=1; loadPortal(true); }
  function clearLocation(triggerLoad=true){ if(!els.location) return; els.location.value=''; if(els.locationSearch) els.locationSearch.value=''; syncLocationSearchText(); renderLocationOptions(); state.selectedRouteId=0; state.selectedRoute=null; state.routeListPage=1; if(triggerLoad) loadPortal(true); }
  function renderLocationOptions(){ if(!els.locationOptions) return; const q=locationSearchQuery(); const opts=locationOptions(); let filtered=q?opts.filter(o=>normalizeLocationText(o.text).indexOf(q)>-1):opts; if(q){ filtered.sort((a,b)=>{ const aa=normalizeLocationText(a.text), bb=normalizeLocationText(b.text); const as=aa.startsWith(q)?0:1, bs=bb.startsWith(q)?0:1; if(as!==bs) return as-bs; return aa.localeCompare(bb); }); } const limited=filtered.slice(0,120); if(!limited.length){ els.locationOptions.innerHTML='<div class="rp-search-empty">Sem lojas encontradas. Experimenta menos letras ou limpa a pesquisa.</div>'; placeLocationPicker(); return; } els.locationOptions.innerHTML='<button type="button" class="rp-search-option '+(!els.location.value?'active':'')+'" data-value="">Todas as lojas / locais</button>'+limited.map(o=>`<button type="button" class="rp-search-option ${String(o.value)===String(els.location.value)?'active':''}" data-value="${escAttr(o.value)}">${esc(o.text||'')}</button>`).join('')+(filtered.length>limited.length?`<div class="rp-search-empty">Mostradas ${limited.length} de ${filtered.length}. Escreve mais para afinar.</div>`:''); placeLocationPicker(); }
  function selectLocationFromText(text){ if(!els.location) return false; const q=normalizeLocationText(text); if(q===''){ clearLocation(); return true; } const opts=locationOptions(); let match=opts.find(o=>normalizeLocationText(o.text)===q); if(!match) match=opts.find(o=>normalizeLocationText(o.text).startsWith(q)); if(!match) match=opts.find(o=>normalizeLocationText(o.text).indexOf(q)>-1); if(match){ chooseLocation(match.value, match.text); return true; } renderLocationOptions(); openLocationPicker(true); return false; }
  async function syncLocations(){ if(!els.location) return; const current=els.location.value||''; const url=new URL(ownerAjaxUrl, window.location.origin); url.searchParams.set('action','routespro_portal_locations'); if(els.client&&els.client.value) url.searchParams.set('client_id',els.client.value); if(els.project&&els.project.value) url.searchParams.set('project_id',els.project.value); if(els.owner&&els.owner.value) url.searchParams.set('owner_user_id',els.owner.value); if(els.from&&els.from.value) url.searchParams.set('date_from',els.from.value); if(els.to&&els.to.value) url.searchParams.set('date_to',els.to.value); let items=[]; try{ const res=await fetch(url.toString(),{credentials:'same-origin'}); items=await res.json().catch(()=>[]); }catch(_){ items=[]; } items=Array.isArray(items)?items:[]; const options=items.map(loc=>{ const id=parseInt(loc.id||0,10); const label=esc(loc.label||loc.name||('Local #'+(loc.id||''))); return `<option value="${id}">${label}</option>`; }).join(''); els.location.innerHTML='<option value="">Loja / Local</option>'+options; if(current && Array.from(els.location.options).some(o=>String(o.value)===String(current))) els.location.value=current; else els.location.value=''; syncLocationSearchText(); renderLocationOptions(); }
  async function refreshPerformanceDashboard(){ if(!els.performanceFragment) return; const url=new URL(ownerAjaxUrl, window.location.origin); url.searchParams.set('action','fieldflow_perf_dashboard_fragment'); url.searchParams.set('title','Growth Hub da Campanha'); if(els.client&&els.client.value) url.searchParams.set('client_id',els.client.value); if(els.project&&els.project.value) url.searchParams.set('project_id',els.project.value); if(els.owner&&els.owner.value) url.searchParams.set('user_id',els.owner.value); if(els.from&&els.from.value) url.searchParams.set('date_from',els.from.value); if(els.to&&els.to.value) url.searchParams.set('date_to',els.to.value); els.performanceFragment.style.opacity='0.55'; try{ const res=await fetch(url.toString(),{credentials:'same-origin'}); const payload=await res.json().catch(()=>null); if(payload&&payload.success&&payload.data&&typeof payload.data.html==='string'){ els.performanceFragment.innerHTML=payload.data.html; } else if(payload&&payload.data&&payload.data.message){ els.performanceFragment.innerHTML='<div class="rp-chart-empty">'+esc(payload.data.message)+'</div>'; } }catch(_){ els.performanceFragment.innerHTML='<div class="rp-chart-empty">Não foi possível atualizar o Growth Hub.</div>'; } finally { els.performanceFragment.style.opacity='1'; } }
