  function fmtKm(v){ if(v===null||v===undefined||v===''||Number.isNaN(parseFloat(v))) return 'Por calcular'; const n=parseFloat(v); return n.toLocaleString('pt-PT',{maximumFractionDigits:1})+' km'; }
