  function routeMeta(r){ if(!r) return {}; return typeof r.meta_json==='string' ? (()=>{try{return JSON.parse(r.meta_json)||{};}catch(_){return {};}})() : (r.meta_json||{}); }
  function routeMetrics(r){ if(!r) return {}; if(r.route_metrics&&typeof r.route_metrics==='object') return r.route_metrics; const meta=routeMeta(r); return meta.route_metrics||meta.portal_summary||meta.generated_plan_summary||meta.original_plan_summary||meta.plan_summary||meta.metrics||{}; }
  function routeDistanceComplete(r){ const m=routeMetrics(r); const status=String(m.distance_status||r?.distance_status||'').toLowerCase(); const routable=(m.endpoints_routable==null?(m.missing_endpoint_count==null||Number(m.missing_endpoint_count)===0):Number(m.endpoints_routable)!==0); return status==='complete'&&routable; }
  function routeKm(r){ if(!r) return null; const metrics=routeMetrics(r); const values=routeDistanceComplete(r)?[r.distance_km,metrics.distance_km,metrics.total_distance_km]:[metrics.known_distance_km,r.known_distance_km]; for(const value of values){ if(value!=null&&value!==''&&!isNaN(parseFloat(value))) return parseFloat(value); } return null; }
  function routeIntegrityLabel(r){ const m=routeMetrics(r); const status=String(m.distance_status||r?.distance_status||'').toLowerCase(); const endpoint=String(m.endpoint_status||r?.endpoint_status||''); if(status==='complete' && (endpoint==='suspicious_start'||endpoint==='suspicious_end'||endpoint==='suspicious_both')) return 'Distância calculada, validar proximidade dos extremos'; if(status==='complete') return 'Distância completa'; if(endpoint==='missing_start') return 'Km conhecidos, falta partida'; if(endpoint==='missing_end') return 'Km conhecidos, falta chegada'; if(endpoint==='missing_both') return 'Km conhecidos, faltam partida e chegada'; return status==='incomplete'?'Km conhecidos, rota incompleta':'Distância por validar'; }
