  function fmtRouteEur(v){ return v===null||v===undefined||v===''||Number.isNaN(parseFloat(v))?'Por calcular':fmtEur(v); }
  function routeOwner(r){ return r?.owner_name || r?.user_name || selectedText(els.owner,'Operativo'); }
