  function dateRange(from,to){ const out=[]; if(!from||!to) return out; const d=new Date(from+'T00:00:00'); const end=new Date(to+'T00:00:00'); while(d<=end){ out.push(d.toISOString().slice(0,10)); d.setDate(d.getDate()+1); } return out; }
  function selectedFilterRange(){ const from=(els.from&&els.from.value)||new Date().toISOString().slice(0,10); const to=(els.to&&els.to.value)||from; return from<=to?{from,to,label:'Período filtrado'}:{from:to,to:from,label:'Período filtrado'}; }
