  function clampPage(page,total){ return Math.min(Math.max(parseInt(page||1,10)||1,1),Math.max(1,total)); }
  /* 9AV/9AY compatibility markers only: p.set('date_from',els.from.value); p.set('date_to',els.to.value); Active 9BA authority uses selectedFilterRange(). */
  function paramsForRouteAgenda(){ const p=new URLSearchParams(); const range=agendaRange(); p.set('date_from',range.from); p.set('date_to',range.to); p.set('limit','1000'); if(els.client&&els.client.value) p.set('client_id',els.client.value); if(els.project&&els.project.value) p.set('project_id',els.project.value); if(els.owner&&els.owner.value) p.set('owner_user_id',els.owner.value); if(!(els.owner&&els.owner.value) && els.location&&els.location.value) p.set('location_id',els.location.value); return {params:p, range}; }
  function keepClientTabVisible(button){ if(!button) return; const bar=button.closest('.rp-tabbar'); if(!bar || bar.scrollWidth<=bar.clientWidth+2) return; const left=button.offsetLeft, right=left+button.offsetWidth, viewLeft=bar.scrollLeft+12, viewRight=bar.scrollLeft+bar.clientWidth-12; if(left>=viewLeft && right<=viewRight) return; const desired=Math.max(0, Math.min(bar.scrollWidth-bar.clientWidth, left-((bar.clientWidth-button.offsetWidth)/2))); bar.scrollTo({left:desired,behavior:'auto'}); }
  function setPanelLifecycle(key,status){ key=String(key||'overview'); status=String(status||'ready'); const panel=root.querySelector('.rp-panel[data-panel="'+key+'"]'); if(!panel) return; state.panelLifecycle[key]=status; panel.dataset.ffPanelLifecycle=status; panel.setAttribute('aria-busy',status==='loading'?'true':'false'); root.dispatchEvent(new CustomEvent('fieldflow:client-panel-lifecycle',{bubbles:false,detail:{panel:key,status,portal:'client',contract:'fieldflow-client-panel-lifecycle-v1'}})); }
  function clientAIScopeKey(){ return [els.client?.value||root.dataset.clientId||'',els.project?.value||root.dataset.projectId||'',els.owner?.value||'',els.location?.value||'',els.from?.value||'',els.to?.value||''].join('|'); }
  let clientPanelSwitchToken=0;
  async function switchPanel(key,options={}){ key=String(key||'overview'); const current=activePanelKey(); const target=root.querySelector('.rp-panel[data-panel="'+key+'"]'); if(!target) return; const remember=options.remember!==false; const changed=current!==key; const token=++clientPanelSwitchToken; const paintStable=root.classList.contains('ff-paint-stable-v1'); const needsLazy=paintStable&&options.prepare!==false&&Array.from(target.querySelectorAll('[data-ff-lazy-panel="1"]')).some(node=>node.dataset.ffLoaded!=='1'); if(needsLazy&&window.FieldFlowUI&&typeof window.FieldFlowUI.loadPanelByKey==='function'){root.dataset.ffPendingPanel=key;target.dataset.ffPanelPending='1';await Promise.resolve(window.FieldFlowUI.loadPanelByKey(root,key));target.removeAttribute('data-ff-panel-pending');if(token!==clientPanelSwitchToken)return;delete root.dataset.ffPendingPanel;} root.dataset.activePanel=key; if(!target.dataset.ffPanelLifecycle)setPanelLifecycle(key,'mount'); let activeButton=null; root.querySelectorAll('.rp-tabbar button[data-panel]').forEach(b=>{const active=(b.dataset.panel||'overview')===key;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');b.setAttribute('tabindex',active?'0':'-1');if(active)activeButton=b;}); root.querySelectorAll('.rp-panel[data-panel]').forEach(panel=>{const active=panel===target;panel.classList.toggle('active',active);panel.hidden=!active;panel.setAttribute('aria-hidden',active?'false':'true');}); if(remember){try{sessionStorage.setItem('fieldflow.client.activePanel',key);}catch(_){}} ensurePortalTableScroll(target); if(key==='analytics' && !state.panelLoads[key])setPanelLifecycle(key,'loading'); const loadTask=Promise.resolve(ensurePanelData(key,false)); loadTask.finally(()=>{if(root.dataset.activePanel===key)setPanelLifecycle(key,'ready');}); if(changed||options.announce===true){const detail={panel:key,portal:'client',source:'client-shell'};target.dispatchEvent(new CustomEvent('routespro:panel-open',{bubbles:true,detail}));target.querySelectorAll('.rp-front-commercial,.rp-front-routes,.routespro-dashboard,.ff-client-briefings,.ff-implementations,.ff-stock-hub,.ff-shopping-results,.rp-team-mail,.rp-team-inbox,.ffp-front').forEach(el=>el.dispatchEvent(new CustomEvent('routespro:panel-open',{bubbles:false,detail:{panel:key,portal:'client',source:'client-shell-module'}})));} /* 9B compatibility marker: window.requestAnimationFrame(()=>keepClientTabVisible(activeButton)) */ keepClientTabVisible(activeButton); }
  function setRouteDateLock(date, routeId){ state.routeDateLocked=false; state.lockedDate=date||''; if(els.from) els.from.disabled=false; if(els.to) els.to.disabled=false; if(els.routeLock){ els.routeLock.classList.toggle('active',!!date); const span=els.routeLock.querySelector('span'); if(span) span.textContent=date ? `Rota #${routeId||state.selectedRouteId||''} aberta em ${date}. O filtro global De/Até permanece ativo.` : 'Filtro global De/Até ativo.'; } }
  function renderOwnerRoutesSummary(){
    if(!els.ownerRoutesSummary) return;
    const agendaRoutes=routesInSelectedRange(state.routeAgenda);
    if(!els.owner||!els.owner.value){
      els.ownerRoutesSummary.innerHTML='<div class="rp-panel-head" style="margin-bottom:8px"><div><h4 style="margin:0">Rotas atribuídas ao operativo</h4><p>Escolhe um operativo para ver os totais de rota do período selecionado.</p></div><span class="rp-pill">De → Até</span></div><div class="rp-chart-empty">Seleciona um operativo para carregar as respetivas rotas e custos.</div>';
      return;
    }
    const range=selectedFilterRange();
    const totals=routeAggregate(agendaRoutes);
    const totalKmLabel=fmtKm(totals.km);
    const costNote=totals.unresolved?totals.unresolved+' rota(s) com custo por calcular':'Total do período filtrado';
    const perPage=10;
    const totalPages=Math.max(1,Math.ceil(agendaRoutes.length/perPage));
    state.ownerRoutesPage=clampPage(state.ownerRoutesPage,totalPages);
    const paged=agendaRoutes.slice((state.ownerRoutesPage-1)*perPage,state.ownerRoutesPage*perPage);
    const list=paged.map(r=>`<button type="button" class="rp-route-summary-item ${String(r.id)===String(state.selectedRouteId)?'active':''}" data-open-route="${esc(r.id)}"><strong>${esc(r.date||'')}</strong><span><b>Rota #${esc(r.id)}</b><br><small>${esc(routeProject(r))} · ${esc(routeOwner(r))} · ${routeStops(r)} PDVs</small></span><span>${fmtKm(routeKm(r))}<br><small>${fmtRouteEur(routeMobilityTotal(r))} total · ${fmtRouteEur(routeToll(r))} port.</small></span></button>`).join('');
    const pages=agendaRoutes.length>perPage?`<div class="rp-table-meta"><div class="rp-meta">${agendaRoutes.length} rotas, página ${state.ownerRoutesPage} de ${totalPages}</div><div class="rp-pagination"><button type="button" class="rp-small" data-summary-page="${state.ownerRoutesPage-1}" ${state.ownerRoutesPage<=1?'disabled':''}>Anterior</button><button type="button" class="rp-small" data-summary-page="${state.ownerRoutesPage+1}" ${state.ownerRoutesPage>=totalPages?'disabled':''}>Seguinte</button></div></div>`:`<div class="rp-meta" style="margin-top:10px">${agendaRoutes.length} rotas visíveis no período.</div>`;
    els.ownerRoutesSummary.innerHTML=`<div class="rp-panel-head" style="margin-bottom:8px"><div><h4 style="margin:0">Rotas atribuídas ao operativo</h4><p>${esc(selectedText(els.owner,'Operativo'))} · ${esc(range.from)} a ${esc(range.to)}. O intervalo De → Até é a única autoridade temporal.</p></div><span class="rp-pill">${agendaRoutes.length} rotas no período</span></div><div class="rp-kpi-grid">${metricCard('Rotas atribuídas',totals.routes,'Período filtrado')}${metricCard('PDVs em rota',totals.stops,'Paragens planeadas')}${metricCard('Kms',totalKmLabel,'Total do período filtrado')}${metricCard('Portagens',aggregateMoney(totals.toll,totals.unresolved),costNote)}${metricCard('Combustível / energia',aggregateMoney(totals.energy,totals.unresolved),costNote)}${metricCard('Custo operacional',aggregateMoney(totals.operational,totals.unresolved),costNote)}${metricCard('Custo deslocação',aggregateMoney(totals.mobility,totals.unresolved),costNote)}</div><div class="rp-summary-controls"><button type="button" class="rp-small primary" id="rpcp-summary-open-routes">Abrir rotas do período</button></div><div class="rp-route-summary-list">${list||'<div class="rp-chart-empty">Sem rotas para os filtros atuais.</div>'}</div>${pages}`;
    els.ownerRoutesSummary.querySelectorAll('[data-open-route]').forEach(btn=>btn.addEventListener('click',()=>openRouteFromAgenda(btn.dataset.openRoute)));
    els.ownerRoutesSummary.querySelectorAll('[data-summary-page]').forEach(btn=>btn.addEventListener('click',()=>{ state.ownerRoutesPage=clampPage(btn.dataset.summaryPage,totalPages); renderOwnerRoutesSummary(); }));
    els.ownerRoutesSummary.querySelector('#rpcp-summary-open-routes')?.addEventListener('click',()=>switchPanel('routes'));
  }
  function renderRouteCalendar(){
    if(!els.routeCalendar) return;
    const range=selectedFilterRange();
    const routes=routesInSelectedRange(state.routes);
    if(els.routeAgendaLabel) els.routeAgendaLabel.textContent=range.from+' → '+range.to;
    if(!routes.length){ els.routeCalendar.innerHTML='<div class="rp-chart-empty">Sem rotas no intervalo De → Até selecionado.</div>'; return; }
    const months=availableRouteMonths(routes);
    const monthCards=months.map(month=>{
      const monthRoutes=routes.filter(r=>routeMonthKey(r)===month);
      const [year,mon]=month.split('-').map(n=>parseInt(n,10));
      const first=new Date(year,mon-1,1);
      const daysInMonth=new Date(year,mon,0).getDate();
      const offset=(first.getDay()+6)%7;
      const byDate=new Map();
      monthRoutes.forEach(r=>{ const d=String(r.date||''); if(!byDate.has(d)) byDate.set(d,[]); byDate.get(d).push(r); });
      const cells=[];
      for(let i=0;i<offset;i++) cells.push('<div class="rp-day-empty"></div>');
      for(let day=1; day<=daysInMonth; day++){
        const date=month+'-'+String(day).padStart(2,'0');
        if(date<range.from || date>range.to){ cells.push('<div class="rp-day-empty"></div>'); continue; }
        const items=byDate.get(date)||[];
        if(!items.length){ cells.push('<div class="rp-day-empty"></div>'); continue; }
        const incomplete=items.some(r=>!routeDistanceComplete(r));
        const totals=routeAggregate(items);
        const kmLabel=fmtKm(totals.km)+(incomplete?' conhecidos':'');
        const totalLabel=aggregateMoney(totals.mobility,totals.unresolved);
        const active=items.some(r=>String(r.id)===String(state.selectedRouteId));
        const financialDetail='Total '+totalLabel+' · Port. '+aggregateMoney(totals.toll,totals.unresolved)+' · Energia '+aggregateMoney(totals.energy,totals.unresolved)+' · Oper. '+aggregateMoney(totals.operational,totals.unresolved);
        cells.push(`<button type="button" class="rp-day-chip ${active?'active':''}" data-open-route="${esc(items[0].id)}" title="${esc(items.length+' rota(s), '+kmLabel+', custo total '+totalLabel+', '+totals.stops+' PDVs. '+financialDetail)}"><span>${day}</span><small>${items.length} rota${items.length===1?'':'s'}<br>${kmLabel} · <strong>${totalLabel}</strong> · ${totals.stops} PDVs</small></button>`);
      }
      return `<div class="rp-month-card"><h5>${esc(monthLabel(month))} · ${monthRoutes.length} rota${monthRoutes.length===1?'':'s'} no período</h5><div class="rp-weekdays"><div class="rp-weekday">Seg</div><div class="rp-weekday">Ter</div><div class="rp-weekday">Qua</div><div class="rp-weekday">Qui</div><div class="rp-weekday">Sex</div><div class="rp-weekday">Sáb</div><div class="rp-weekday">Dom</div></div><div class="rp-month-days">${cells.join('')}</div></div>`;
    }).join('');
    els.routeCalendar.innerHTML=`<div class="rp-meta" style="margin:2px 0 10px">Calendário validado exclusivamente por <strong>De → Até</strong>: ${esc(range.from)} a ${esc(range.to)}.</div><div class="rp-route-calendar-range">${monthCards}</div>`;
    els.routeCalendar.querySelectorAll('[data-open-route]').forEach(btn=>btn.addEventListener('click',()=>openRouteFromAgenda(btn.dataset.openRoute)));
  }

  async function openRouteFromAgenda(routeId){
    const r=(state.routeAgenda||state.routes||[]).find(x=>String(x.id)===String(routeId)) || (state.routes||[]).find(x=>String(x.id)===String(routeId));
    if(r&&r.date){ state.routeListPage=1; setRouteDateLock(String(r.date), r.id); }
    switchPanel('routes');
    await selectRoute(routeId,true,false);
  }
  async function loadRoutesRange(){ const cfg=paramsForRouteAgenda(); state.routeAgendaRange=cfg.range; const data=await j(api+'routes?'+cfg.params.toString()).catch(()=>({routes:[]})); const routes=sortedRoutes(Array.isArray(data.routes)?data.routes:[]); state.routeAgenda=routes; state.routes=routes; if(state.selectedRouteId && state.routes.some(r=>String(r.id)===String(state.selectedRouteId))){ await selectRoute(state.selectedRouteId,false,false); } renderOwnerRoutesSummary(); renderRouteCalendar(); renderRouteList(); renderReports(); }
  // 9D6: localized display only; original status values remain unchanged in forms and REST.
  function statusLabel(status){ const value=String(status||'pending'); const labels={planned:'Planeada',draft:'Rascunho',in_progress:'Em curso',completed:'Concluída',done:'Concluída',pending:'Pendente',failed:'Não realizada',canceled:'Cancelada',cancelled:'Cancelada',justified:'Justificada',closed:'Fechada',reopened:'Reaberta',open:'Aberta',submitted:'Submetida'}; return labels[value.toLowerCase()]||value; }
  function badge(status){ const cls=(status||'pending').replace(/[^a-z_]/gi,'_'); return `<span class="rp-badge ${cls}">${esc(statusLabel(status))}</span>`; }
  function trendDelta(current, previous, suffix=''){ const c=parseFloat(current||0)||0; const p=parseFloat(previous||0)||0; const d=+(c-p).toFixed(1); if(d>0) return `▲ +${d}${suffix}`; if(d<0) return `▼ ${d}${suffix}`; return `• 0${suffix}`; }
  function metricCard(label,val,small,delta){ return `<div class="rp-kpi"><span>${label}</span><strong>${val}</strong><small style="display:block;margin-top:6px;color:#64748b">${small||''}${delta?`<br><span style=\"color:#0f172a;font-weight:600\">${delta}</span>`:''}</small></div>`; }
  function renderKpis(stats){ const prev=stats?.previous_summary||{}; const rank=stats?.rankings||{}; const perf=(stats&&stats.team_performance&&typeof stats.team_performance==='object')?stats.team_performance:{}; const leader=(perf.leader&&typeof perf.leader==='object')?perf.leader:null; els.kpis.innerHTML=[metricCard('Rotas',stats?.total_routes||0,'Total no período',trendDelta(stats?.total_routes||0, prev?.total_routes||0)),metricCard('Concluídas',stats?.completed_routes||0,'Rotas fechadas',trendDelta(stats?.completed_routes||0, prev?.completed_routes||0)),metricCard('Paragens',stats?.total_stops||0,'Execução acumulada',trendDelta(stats?.total_stops||0, prev?.total_stops||0)),metricCard('% Execução',(stats?.done_rate||0)+'%','Conclusão de paragens',trendDelta(stats?.done_rate||0, prev?.done_rate||0,'%')),metricCard('On time',stats?.on_time_rate==null?'n.d.':(stats.on_time_rate+'%'),'Dentro da janela horária'),metricCard('Média visita',stats?.avg_stop_minutes?stats.avg_stop_minutes+' min':'n.d.','Tempo médio por paragem'),metricCard('Top campanha',rank?.top_project||'n.d.',rank?.top_project_value?`${rank.top_project_value} paragens concluídas`:'Sem liderança no período'),metricCard('Top owner',rank?.top_owner||'n.d.',rank?.top_owner_value?`${rank.top_owner_value} paragens concluídas`:'Sem liderança no período')].join(''); const perfMode=perf?.mode||'team'; void perfMode; void leader; }
  function renderCommercialKpis(commercial){ const cs=(commercial&&commercial.stats)||{}; if(els.commercialKpis){ els.commercialKpis.innerHTML=[metricCard('PDVs visíveis',cs.total_visible||0,'Resultado atual da base comercial'),metricCard('Com coordenadas',cs.with_coords||0,'Prontos para mapa e rota'),metricCard('Origem Google',cs.google_count||0,'Registos vindos de integração Google'),metricCard('Validados',cs.validated_count||0,'Qualidade confirmada no âmbito ativo')].join(''); } setHeroMetric('rpcp-hero-scope',selectedText(els.client,'Todos os clientes')+' / '+selectedText(els.project,'Todas as campanhas'),'Escopo operacional sincronizado com o portal.'); setHeroMetric('rpcp-hero-commercial',cs.total_visible||0,`PDVs visíveis, ${cs.google_count||0} origem Google.`); setHeroMetric('rpcp-hero-validation',`${cs.validated_count||0} / ${cs.with_coords||0}`,'Validados e com coordenadas prontos para operação.'); setHeroMetric('rpcp-hero-period',`${esc(els.from?.value||'')} a ${esc(els.to?.value||'')}`,'Janela temporal ativa no resumo executivo.'); }
  function renderChart(rows){ rows=Array.isArray(rows)?rows:[]; if(!rows.length){ els.chart.innerHTML='<div class="rp-chart-empty">Sem dados no período selecionado.</div>'; return; } const primary=themeVar('--rp-primary','#2563eb'),muted=themeVar('--ff-muted','#475569'),text=themeVar('--ff-text','#0f172a'),border=themeVar('--ff-border','#cbd5e1'); const values=rows.map(r=>parseFloat(r.done_rate||0)||0); const max=Math.max(100,...values); const barW=rows.length>12?34:50; const gap=14; const width=Math.max(380, rows.length*(barW+gap)+40); const height=240; const bars=rows.map((r,i)=>{ const x=20+i*(barW+gap); const val=parseFloat(r.done_rate||0)||0; const h=Math.max(8,Math.round((val/max)*160)); const y=190-h; const label=String(r.date||'').slice(5); return `<g><rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="12" fill="${escAttr(primary)}"></rect><text x="${x+barW/2}" y="206" text-anchor="middle" font-size="11" fill="${escAttr(muted)}">${esc(label)}</text><text x="${x+barW/2}" y="${Math.max(18,y-8)}" text-anchor="middle" font-size="11" fill="${escAttr(text)}">${val}%</text></g>`; }).join(''); els.chart.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Execução por dia"><line x1="14" y1="190" x2="${width-12}" y2="190" stroke="${escAttr(border)}" stroke-width="1"></line>${bars}</svg>`; }
