  function openClientIntelTarget(target){const safe=String(target||'').replace(/[^a-z0-9_-]/gi,'');if(!safe)return false;const tab=root.querySelector('[data-panel="'+safe+'"],[data-target="'+safe+'"],[data-rp-tab="'+safe+'"],[data-panel-target="'+safe+'"]');if(tab){tab.click();return true;}const panel=root.querySelector('.rp-panel[data-panel="'+safe+'"]');if(panel){panel.scrollIntoView({behavior:'smooth',block:'start'});return true;}return false;}function bindClientIntelActions(){if(!els.aiInsights)return;els.aiInsights.querySelectorAll('[data-ff-intel-action]').forEach(btn=>btn.addEventListener('click',()=>{const target=String(btn.dataset.ffIntelTarget||'analytics'),kind=String(btn.dataset.ffIntelKind||'filter');window.dispatchEvent(new CustomEvent('fieldflow:intelligence-action',{detail:{id:btn.dataset.ffIntelAction||'',target,kind,source:'client'}}));if(kind==='export'&&els.analyticsExportXls){els.analyticsExportXls.click();return;}if(target==='analytics'&&els.analyticsChart){els.analyticsChart.scrollIntoView({behavior:'smooth',block:'start'});return;}if(target==='routes'&&els.routesTable){els.routesTable.closest('section,article,div')?.scrollIntoView({behavior:'smooth',block:'start'});return;}openClientIntelTarget(target);}));}
  function clientExplainabilityHtml(data){const x=data?.explainability||{},uses=Array.isArray(x.uses)?x.uses:[],rules=Array.isArray(x.rules)?x.rules:[],no=Array.isArray(x.does_not_do)?x.does_not_do:[],confidence=x.confidence||{};if(!uses.length&&!rules.length)return'';const list=items=>items.slice(0,6).map(i=>`<li>${typeof i==='object'?`<strong>${esc(i.label||'')}</strong>${i.detail?' · '+esc(i.detail):''}`:esc(i)}</li>`).join('');return `<details class="rp-ai-explain"><summary>Como funciona esta análise?</summary><div class="rp-ai-explain-body"><p>${esc(x.summary||'A leitura usa apenas dados FieldFlow do âmbito atual.')}</p><div class="rp-ai-explain-grid"><div><h6>Dados utilizados</h6><ul>${list(uses)}</ul></div><div><h6>Regras de interpretação</h6><ul>${list(rules)}</ul></div><div><h6>O que não faz</h6><ul>${list(no)}</ul></div><div><h6>Confiança</h6><p>${esc(confidence.detail||'A confiança depende da cobertura e consistência dos dados disponíveis.')}</p></div></div>${x.period?`<div class="rp-ai-explain-confidence">Âmbito temporal: <strong>${esc(x.period)}</strong></div>`:''}</div></details>`;}
  function renderClientAI(data){if(!els.aiInsights)return;const briefing=data?.briefing||{},stocks=data?.stocks||{},priorities=Array.isArray(briefing.priorities)?briefing.priorities:[],briefingBox=briefing.primary_title?`<div class="rp-ai-briefing"><div><h5>Prioridade do briefing: ${esc(briefing.primary_title)}</h5><p>${briefing.valid_from||briefing.valid_to?`Válido de ${esc(briefing.valid_from||'')} a ${esc(briefing.valid_to||'')}. `:''}A IA cruza estas prioridades apenas com reportes submetidos que continuam ativos.</p>${priorities.length?`<div class="rp-ai-briefing-list">${priorities.slice(0,5).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</div><span class="rp-ai-briefing-badge">Briefing first</span></div>`:'',stockBox=stocks.available?`<div class="rp-ai-briefing" style="border-color:#86efac;background:linear-gradient(145deg,#f0fdf4,#fff 68%)"><div><h5 style="color:#166534">Contexto de stock: ${esc(stocks.snapshot_date||'snapshot publicado')}</h5><p>${esc(stocks.zero_count||0)} ruturas, ${esc(stocks.low_count||0)} linhas de stock baixo e ${esc(stocks.negative_count||0)} valores negativos em ${esc(stocks.stores||0)} lojas. A IA usa estes dados como sinal operacional, sem substituir a validação física.</p></div><span class="rp-ai-briefing-badge" style="background:#16a34a">Stock context</span></div>`:'';els.aiInsights.innerHTML=briefingBox+stockBox+clientDecisionScoresHtml(data)+clientIntelHtml(data)+`<div class="rp-ai-summary"><strong>${esc(data.headline||'Leitura do período')}</strong><p>${esc(data.summary||'Ainda não existem dados suficientes para uma análise detalhada.')}</p></div><div class="rp-ai-grid">${clientAIItems(data.highlights,'highlights','Sem destaques relevantes.')}${clientAIItems(data.risks,'risks','Sem riscos relevantes detetados.')}${clientAIItems(data.actions,'actions','Continua a acompanhar a execução.')}</div>${clientExplainabilityHtml(data)}<div class="rp-ai-meta"><span>Confiança: ${esc(data.confidence||'n.d.')}</span><span>${esc(data.provider||'Motor FieldFlow')}</span><span>Submissões ativas e último stock publicado</span><span>${esc(data.generated_at||'')}</span></div>`;bindClientIntelActions();}
  async function loadClientAI(refresh=false){if(!els.aiInsights)return;const scopeKey=clientAIScopeKey();if(!refresh&&state.clientAI.loaded&&state.clientAI.scopeKey===scopeKey)return;if(state.clientAI.loading&&state.clientAI.scopeKey===scopeKey)return;state.clientAI.loading=true;state.clientAI.scopeKey=scopeKey;els.aiInsights.setAttribute('aria-busy','true');if(els.aiRefresh){els.aiRefresh.disabled=true;els.aiRefresh.textContent='A analisar...';}if(!state.clientAI.loaded||refresh)els.aiInsights.innerHTML='<div class="rp-chart-empty rp-ai-stable-placeholder">A cruzar execução, formulários e métricas...</div>';try{const body=Object.fromEntries(paramsForStats().entries());body.audience='client';body.refresh=refresh?1:0;const [data,store]=await Promise.all([j(api+'analytics/ai-insights',{method:'POST',headers:{'X-WP-Nonce':nonce,'Content-Type':'application/json'},body:JSON.stringify(body)}),j(api+'analytics/store-intelligence',{method:'POST',headers:{'X-WP-Nonce':nonce,'Content-Type':'application/json'},body:JSON.stringify(body)}).catch(()=>null)]);if(store&&store.available){data.store_intelligence=store;data.contextual_predictive_intelligence=store.contextual_predictive||{};}renderClientAI(data);state.clientAI.loaded=true;}catch(err){els.aiInsights.innerHTML='<div class="rp-chart-empty">Não foi possível gerar a análise inteligente neste momento.</div>';state.clientAI.loaded=false;}finally{state.clientAI.loading=false;els.aiInsights.setAttribute('aria-busy','false');if(els.aiRefresh){els.aiRefresh.disabled=false;els.aiRefresh.textContent='Atualizar análise';}}}
  let portalAskContextKey='';
