  function portalAskLoading(){if(!els.askThread)return null;const id='rpcp-ask-loading-'+Date.now();els.askThread.insertAdjacentHTML('beforeend',`<article class="rp-ask-message" id="${id}"><div class="rp-ask-loading">A cruzar o contexto FieldFlow...</div></article>`);portalAskScroll();return root.querySelector('#'+id);}
  function portalAskAnswer(data,placeholder){if(!els.askThread)return;if(placeholder&&placeholder.parentNode)placeholder.parentNode.removeChild(placeholder);const points=Array.isArray(data?.key_points)?data.key_points:[],evidence=Array.isArray(data?.evidence)?data.evidence:[],followups=Array.isArray(data?.followups)?data.followups:[];const pointHtml=points.length?`<ul class="rp-ask-points">${points.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'';const evidenceHtml=evidence.length?`<div class="rp-ask-evidence">${evidence.slice(0,8).map(x=>{const kind=String(x?.kind||'observed'),kindLabels={observed:'Observado',projected:'Projetado',learned:'Aprendido',advisory:'Advisory'};return `<span class="is-${escAttr(kind)}" title="${escAttr(x?.source||'FieldFlow')}"><b>${esc(kindLabels[kind]||'Evidência')}</b> ${esc(x?.label||'Fonte')}: ${esc(x?.value||'')}</span>`;}).join('')}</div>`:'';const followHtml=followups.length?`<div class="rp-ask-followups">${followups.slice(0,4).map(x=>`<button type="button" data-rpcp-ask-question="${escAttr(x)}">${esc(x)}</button>`).join('')}</div>`:'';const confidence=data?.confidence_score!=null?`${esc(data.confidence_score)}/100`:esc(data?.confidence||'n.d.');els.askThread.insertAdjacentHTML('beforeend',`<article class="rp-ask-message"><strong>FieldFlow</strong><p>${esc(data?.answer||'Não foi possível produzir uma resposta segura.')}</p>${pointHtml}${evidenceHtml}<div class="rp-ask-meta"><span>${esc(data?.provider||'Motor FieldFlow')}</span><span>Confiança ${confidence}</span><span>${data?.source==='ai'?'IA fundamentada':'Resposta determinística'}</span><span>Read-only</span></div>${followHtml}</article>`);portalAskScroll();}
  function portalAskError(message,placeholder){if(!els.askThread)return;if(placeholder&&placeholder.parentNode)placeholder.parentNode.removeChild(placeholder);els.askThread.insertAdjacentHTML('beforeend',`<article class="rp-ask-message"><strong>FieldFlow</strong><p>${esc(message||'Não foi possível responder neste momento.')}</p><div class="rp-ask-meta"><span>O Analytics base continua operacional</span></div></article>`);portalAskScroll();}
  async function askPortalFieldFlow(question){question=String(question||'').trim();if(!question||!els.askThread)return;const body=Object.fromEntries(paramsForStats().entries());body.audience='client';const contextKey=JSON.stringify({client_id:body.client_id||'',project_id:body.project_id||'',route_id:body.route_id||'',user_id:body.user_id||'',location_id:body.location_id||'',from:body.from||'',to:body.to||'',category:body.category||'',product:body.product||''});if(portalAskContextKey&&portalAskContextKey!==contextKey)portalAskReset();portalAskContextKey=contextKey;portalAskUser(question);const placeholder=portalAskLoading();if(els.askInput)els.askInput.value='';if(els.askSubmit){els.askSubmit.disabled=true;els.askSubmit.textContent='A responder...';}try{body.question=question;body.history=portalAskHistory.slice(-6);const data=await j(api+'analytics/ask',{method:'POST',headers:{'X-WP-Nonce':nonce,'Content-Type':'application/json'},body:JSON.stringify(body)});portalAskAnswer(data,placeholder);portalAskHistory.push({role:'user',content:question},{role:'assistant',content:String(data?.answer||'')});if(portalAskHistory.length>12)portalAskHistory=portalAskHistory.slice(-12);}catch(err){portalAskError(err?.message||'Não foi possível responder neste momento.',placeholder);}finally{if(els.askSubmit){els.askSubmit.disabled=false;els.askSubmit.textContent='Perguntar';}}}
  if(els.askForm)els.askForm.addEventListener('submit',ev=>{ev.preventDefault();askPortalFieldFlow(els.askInput?.value||'');});
