  const portalAskBox=root.querySelector('#rpcp-ask-fieldflow');if(portalAskBox)portalAskBox.addEventListener('click',ev=>{const q=ev.target.closest('[data-rpcp-ask-question]');if(!q)return;ev.preventDefault();const text=String(q.dataset.rpcpAskQuestion||'');if(els.askInput)els.askInput.value=text;askPortalFieldFlow(text);});
  if(els.askInput)els.askInput.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key==='Enter'){ev.preventDefault();askPortalFieldFlow(els.askInput.value);}});
  function renderMonthlyExecutive(stats){
    if(!els.monthlyExecutive)return;
    const m=stats&&stats.monthly_executive&&typeof stats.monthly_executive==='object'?stats.monthly_executive:null;
    if(!m||!m.primary_kpis){els.monthlyExecutive.innerHTML='<div class="rp-chart-empty">Sem dados suficientes para preparar o resumo executivo deste período.</div>';return;}
    const p=m.primary_kpis||{},s=m.secondary_kpis||{},tr=m.trends||{},health=m.health||{},risks=Array.isArray(m.risk_locations)?m.risk_locations:[],signals=Array.isArray(m.commercial_signals)?m.commercial_signals:[];
    const pct=v=>Number(v||0).toLocaleString('pt-PT',{maximumFractionDigits:1})+'%';
    const num=(v,d=0)=>Number(v||0).toLocaleString('pt-PT',{maximumFractionDigits:d,minimumFractionDigits:d});
    const eur=v=>Number(v||0).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';
    const trendBadge=(item)=>{if(!item||!item.available)return'<em>Sem comparação</em>';const d=Number(item.delta||0),suffix=item.unit==='pp'?' pp':'';return `<em class="${d>0?'is-up':(d<0?'is-down':'')}">${d>0?'↑ ':d<0?'↓ ':'→ '}${esc(Math.abs(d).toLocaleString('pt-PT',{maximumFractionDigits:1})+suffix)} vs período anterior</em>`;};
    const kpi=(item,trend)=>`<div class="rp-monthly-kpi"><span>${esc(item?.label||'Indicador')}</span><strong>${esc((item?.unit==='%'?pct(item?.value):num(item?.value,1)))}</strong><small>${esc(item?.note||'')}</small>${trendBadge(trend)}</div>`;
    const riskHtml=risks.length?risks.slice(0,5).map(r=>`<div class="rp-monthly-risk"><div><strong>${esc(r.location_name||'Loja')}</strong><small>${esc([r.city||'',(r.completed_visits||0)+'/'+(r.planned_visits||0)+' visitas'].filter(Boolean).join(' · '))}</small></div><strong>${esc(pct(r.execution_rate||0))}</strong></div>`).join(''):'<div class="rp-chart-empty">Sem PDVs pendentes neste âmbito.</div>';
    const signalHtml=signals.length?signals.slice(0,4).map(x=>`<div class="rp-monthly-risk"><div><strong>${esc(x.label||'Indicador')}</strong><small>${esc(x.note||'Métrica configurada no Analytics')}</small></div><strong>${esc(String(x.value??'')+(x.unit||''))}</strong></div>`).join(''):'<div class="rp-chart-empty">Os widgets configurados continuam disponíveis abaixo.</div>';
    const secondary=[['Visitas',`${s.visits_completed||0}/${s.visits_planned||0}`],['Justificadas',s.visits_justified||0],['Pendentes',s.visits_remaining||0],['Mobilidade',`${num(s.mobility_distance_km||0,0)} km`],['Custo deslocação',eur(s.mobility_total_cost_eur||0)],['Custo / visita',s.mobility_cost_per_visit_eur==null?'n.d.':eur(s.mobility_cost_per_visit_eur)],['Sugestões encomenda',s.order_suggestions||0],['Caixas sugeridas',num(s.order_boxes||0,0)]].map(x=>`<span>${esc(x[0])}: <strong>${esc(x[1])}</strong></span>`).join('');
    els.monthlyExecutive.innerHTML=`<div class="rp-monthly-head"><div><h4>Este mês em 30 segundos</h4><p>${esc(m?.period?.label||'Período selecionado')} · leitura executiva automática</p></div><span class="rp-monthly-health is-${esc(health.status||'watch')}">${esc(health.label||'Acompanhar')}</span></div><div class="rp-monthly-narrative"><strong>Resumo executivo</strong>${esc(m.narrative||'Sem narrativa disponível.')}</div><div class="rp-monthly-primary">${kpi(p.execution,tr.execution)}${kpi(p.coverage,null)}${kpi(p.route_completion,tr.routes)}</div><div class="rp-monthly-secondary">${secondary}</div><div class="rp-monthly-detail"><div class="rp-monthly-box"><h5>PDVs a acompanhar</h5>${riskHtml}</div><div class="rp-monthly-box"><h5>Sinais comerciais</h5>${signalHtml}</div></div>`;
  }
  function renderTeamPerformance(stats){
    if(!els.teamPerformance) return;
    const perf=stats&&stats.team_performance&&typeof stats.team_performance==='object'?stats.team_performance:{};
    const members=Array.isArray(perf.members)?perf.members:[];
    const mode=String(perf.mode||'team');
    const summary=perf.summary||{};
    const focus=(perf.focus&&typeof perf.focus==='object')?perf.focus:null;
    const leader=(perf.leader&&typeof perf.leader==='object')?perf.leader:null;
    const fmtPct=v=>(Number(v||0)).toLocaleString('pt-PT',{maximumFractionDigits:1})+'%';
    if(els.teamPerformanceTitle) els.teamPerformanceTitle.textContent=mode==='team'?'Performance da equipa':'Performance individual';
    if(els.teamPerformanceScope) els.teamPerformanceScope.textContent=mode==='team'?'Equipa completa':(focus?.name||selectedText(els.owner,'Individual'));
    if(els.teamPerformanceCopy) els.teamPerformanceCopy.textContent=mode==='team'?'Comparação transparente por elemento. As métricas de perguntas abaixo agregam toda a equipa enquanto não selecionares um operativo.':'O Analytics, as perguntas e os reportes abaixo estão filtrados apenas para o operativo selecionado.';
    if(!members.length){ els.teamPerformance.innerHTML='<div class="rp-chart-empty">Sem dados suficientes para calcular performance neste período.</div>'; return; }
    const primary=mode==='team'?(leader||members[0]):(focus||members[0]);
    const leadTitle=mode==='team'?'Melhor performance no período':'Leitura individual';
    const lead=`<div class="rp-performance-leader"><span>${esc(leadTitle)}</span><h5>${esc(primary.name||'Operativo')}</h5><strong>${esc(Number(primary.performance_index||0).toLocaleString('pt-PT',{maximumFractionDigits:1}))}/100</strong><p>${esc(primary.completed_visits||0)}/${esc(primary.planned_visits||0)} visitas · ${esc(fmtPct(primary.execution_rate))} execução · ${esc(primary.reports||0)} reportes · ${esc(primary.question_responses||0)} respostas</p></div>`;
    const visible=(mode==='team'?members.slice(0,8):[primary]).map(m=>`<div class="rp-performance-row"><span class="rp-performance-pos">${mode==='team'?esc(m.position||'•'):'•'}</span><div class="rp-performance-name"><strong>${esc(m.name||'Operativo')}</strong><small>${esc(m.completed_visits||0)}/${esc(m.planned_visits||0)} visitas · ${esc(m.routes||0)} rotas</small></div><div class="rp-performance-number"><strong>${esc(Number(m.performance_index||0).toLocaleString('pt-PT',{maximumFractionDigits:1}))}</strong><small>índice</small></div><div class="rp-performance-number"><strong>${esc(fmtPct(m.execution_rate))}</strong><small>execução</small></div><div class="rp-performance-number"><strong>${esc(m.question_responses||0)}</strong><small>respostas</small></div></div>`).join('');
    const note=mode==='team'?`${Number(summary.members||members.length)} elementos · ${Number(summary.reports||0)} reportes válidos · ${Number(summary.question_responses||0)} respostas de perguntas. Índice: ${perf.score_basis||'execução e cobertura de reportes.'}`:`${Number(primary.reports||0)} reportes válidos · ${Number(primary.question_responses||0)} respostas de perguntas. Esta vista não compara o elemento com colegas.`;
    els.teamPerformance.innerHTML=`<div class="rp-team-performance-grid">${lead}<div class="rp-performance-members">${visible}</div></div><div class="rp-performance-scope-note">${esc(note)}</div>`;
  }
  function renderAnalytics(stats){
    updateAnalyticsReportMeta();
    if(!els.analyticsKpis || !els.analyticsChart || !els.analyticsTables) return;
    const s=stats||{}; const prev=s?.previous_summary||{}; const rank=s?.rankings||{}; const perf=s?.team_performance||{}; const leader=perf?.leader||null;
    renderMonthlyExecutive(s);
    renderTeamPerformance(s);
    const baseKpis=[metricCard('Rotas',s?.total_routes||0,'Total no período',trendDelta(s?.total_routes||0,prev?.total_routes||0)),metricCard('Concluídas',s?.completed_routes||0,'Rotas fechadas',trendDelta(s?.completed_routes||0,prev?.completed_routes||0)),metricCard('Paragens',s?.total_stops||0,'Execução acumulada',trendDelta(s?.total_stops||0,prev?.total_stops||0)),metricCard('% Execução',(s?.done_rate||0)+'%','Conclusão de paragens',trendDelta(s?.done_rate||0,prev?.done_rate||0,'%')),metricCard('Top campanha',rank?.top_project||'n.d.',rank?.top_project_value?`${rank.top_project_value} paragens concluídas`:'Sem liderança no período'),metricCard(String(perf?.mode||'team')==='team'?'Melhor performance':'Operativo',String(perf?.mode||'team')==='team'?(leader?.name||'n.d.'):(perf?.focus?.name||selectedText(els.owner,'Individual')),String(perf?.mode||'team')==='team'?(leader?`${Number(leader.performance_index||0).toLocaleString('pt-PT',{maximumFractionDigits:1})}/100 · ${Number(leader.execution_rate||0).toLocaleString('pt-PT',{maximumFractionDigits:1})}% execução`:'Sem dados suficientes'):(perf?.focus?`${Number(perf.focus.performance_index||0).toLocaleString('pt-PT',{maximumFractionDigits:1})}/100 · leitura individual`:'Sem dados suficientes'))];
    const analytics=s.form_analytics||{};
    const orderNumber=(value,fallback=10)=>{const parsed=parseInt(value,10);return Number.isFinite(parsed)?parsed:fallback;};
    // A API já entrega dashboards e widgets pela mesma ordem canónica da aplicação de campo.
    // O portal preserva essa sequência e usa o índice apenas como garantia estável após filtros.
    const metrics=(Array.isArray(analytics.metrics)?analytics.metrics:[]).map((metric,index)=>({...metric,_canonical_index:index}));
    const dashboards=(Array.isArray(analytics.dashboards)?analytics.dashboards:[]).map((dashboard,index)=>({...dashboard,_canonical_index:index}));
    const metricSort=(a,b)=>{const byOrder=orderNumber(a?.sort_order,10)-orderNumber(b?.sort_order,10);return byOrder||orderNumber(a?._canonical_index,0)-orderNumber(b?._canonical_index,0);};
    state.analyticsEvidenceGroups={};
    const categoryOptions=Array.from(new Set(metrics.flatMap(m=>Array.isArray(m.category_options)?m.category_options:[]).map(v=>String(v||'').trim()).filter(Boolean))).sort((a,b)=>a.localeCompare(b,'pt'));
    const productOptions=Array.from(new Set(metrics.flatMap(m=>Array.isArray(m.product_options)?m.product_options:[]).map(v=>String(v||'').trim()).filter(Boolean))).sort((a,b)=>a.localeCompare(b,'pt'));
    let analyticsFilterReset=false;
    if(state.analyticsCategory && !categoryOptions.includes(state.analyticsCategory)){ state.analyticsCategory=''; state.analyticsProduct=''; analyticsFilterReset=true; }
    if(state.analyticsProduct && !productOptions.includes(state.analyticsProduct)){ state.analyticsProduct=''; analyticsFilterReset=true; }
    if(els.analyticsCategory){ els.analyticsCategory.innerHTML='<option value="">Todas as categorias</option>'+categoryOptions.map(v=>`<option value="${escAttr(v)}">${esc(v)}</option>`).join(''); els.analyticsCategory.value=state.analyticsCategory||''; }
    if(els.analyticsProduct){ const filteredProducts=state.analyticsCategory?productOptions.filter(v=>v.indexOf(state.analyticsCategory+' | ')===0):productOptions; els.analyticsProduct.innerHTML='<option value="">Todos os produtos</option>'+filteredProducts.map(v=>`<option value="${escAttr(v)}">${esc(v)}</option>`).join(''); els.analyticsProduct.value=state.analyticsProduct||''; }
    if(analyticsFilterReset){ window.setTimeout(()=>loadPortal(false),0); }
    const dashboardById={};
    const dashList=[];
    dashboards.forEach(d=>{const id=String(d.id||0);if(dashboardById[id])return;dashboardById[id]=d;dashList.push(d);});
    metrics.forEach(m=>{const id=String(m.dashboard_id||0);if(dashboardById[id])return;const fallback={id:m.dashboard_id||0,title:m.dashboard_title||'Analytics operacional',description:'',layout_type:'mixed',sort_order:m.dashboard_sort_order??999,_canonical_index:dashList.length};dashboardById[id]=fallback;dashList.push(fallback);});
    dashList.sort((a,b)=>{const byOrder=orderNumber(a?.sort_order,999)-orderNumber(b?.sort_order,999);return byOrder||orderNumber(a?._canonical_index,0)-orderNumber(b?._canonical_index,0);});
    const kpiMetrics=metrics.filter(m=>m.chart_type==='kpi'||String(m.show_kpi||'0')==='1');
    const kpis=kpiMetrics.map(m=>metricCard(m.metric_label,m.value==null?'Sem dados':m.value,m.note||m.aggregation||''));
    els.analyticsKpis.innerHTML=(kpis.length?kpis:baseKpis).join('');
    if(!dashList.length){
      const rows=Array.isArray(s.by_day)?s.by_day:[];
      if(!rows.length){ els.analyticsChart.innerHTML='<div class="rp-chart-empty">Sem dashboards analíticos configurados para este âmbito.</div>'; els.analyticsTables.innerHTML='<div class="rp-chart-empty">Cria dashboards no Intelligence Center para o cliente ver a estrutura mesmo antes de existirem respostas.</div>'; return; }
