    function isFrontsMetric(m){if(String(m?.question_type||'')==='order_suggestion'||String(m?.question_type||'')==='share_space_matrix')return false;if(String(m?.is_fronts_metric||'0')==='1'||String(m?.question_type||'')==='product_matrix'||m?.fronts_summary)return true;return (Array.isArray(m?.rows)?m.rows:[]).some(r=>r&&((r.before!==undefined&&r.before!=='')||(r.after!==undefined&&r.after!=='')));}
