    function shareSpaceInlineHtml(m,compact=false){if(!isShareSpaceMetric(m))return'';const s=m.share_space_summary||{},rows=Array.isArray(m.rows)?m.rows:[],series=Array.isArray(m.series)?m.series:[];const fmt=v=>new Intl.NumberFormat('pt-PT',{maximumFractionDigits:1}).format(Number(v||0));const signed=v=>`${Number(v||0)>0?'+':''}${fmt(v)}`;const summary=`<div class="rp-share-summary">${metricCard('Quota média PR',fmt(s.avg_share??m.value)+'%','Média ponderada')}${metricCard('Desvio médio',signed(s.avg_gap)+' pp','Face ao objetivo')}${metricCard('Objetivo atingido',s.on_target??0,'Comparações no alvo')}${metricCard('Abaixo objetivo',s.below_target??0,'Comparações a corrigir')}${metricCard('Frentes PR',fmt(s.pr_fronts_total),'Total registado')}${metricCard('Frentes concorrência',fmt(s.competitor_fronts_total),'Total registado')}</div>`;const source=(series.length?series:rows.map(r=>({label:r.metric||r.product||'Share Space',value:r.pr_share||0,target:r.target||0,gap:r.gap||0}))).slice(0,16);const bars=source.map(x=>{const row=rows.find(r=>(r.metric||r.product)===x.label)||{},value=Math.max(0,Math.min(100,Number(x.value??row.pr_share??0))),target=Math.max(0,Math.min(100,Number(x.target??row.target??0))),gap=Number(x.gap??row.gap??(value-target));return `<div class="rp-share-row"><strong>${esc(x.label||'Comparação')}</strong><span class="rp-share-track" title="Quota PR ${fmt(value)}%, objetivo ${fmt(target)}%"><i style="width:${value}%"></i><b style="left:${target}%"></b></span><em class="${gap<0?'is-below':'is-ok'}">${fmt(value)}% · ${signed(gap)} pp</em></div>`;}).join('');const total=Number(s.metric_count||rows.length||0),stores=Number(s.stores_count||new Set(rows.map(r=>String(r.location_id||r.location||'')).filter(Boolean)).size||0);return `<section class="rp-share-space ${compact?'is-compact':''}">${compact?'':'<div class="rp-share-note">Leitura calculada a partir das frentes introduzidas. As percentagens não são editáveis e são recalculadas no servidor.</div>'}${summary}${!compact&&bars?`<div class="rp-share-bars">${bars}</div>`:''}<div class="rp-meta">${total} ${total===1?'comparação':'comparações'} · ${stores} ${stores===1?'loja':'lojas'}</div></section>`;}
    function orderInlineHtml(m){const rows=(Array.isArray(m.rows)?m.rows:[]).filter(r=>r&&((r.order_qty!==undefined&&r.order_qty!==null&&String(r.order_qty).trim()!=='')||String(r.notes||'').trim()!==''));const preview=rows.slice(0,10),boxes=rows.reduce((n,r)=>n+(parseFloat(r.order_qty||0)||0),0),units=rows.reduce((n,r)=>n+(parseFloat(r.units_total||0)||0),0),stores=new Set(rows.map(r=>String(r.location_id||r.location||'')).filter(Boolean)).size;const body=preview.map(r=>`<tr><td class="col-location" data-label="Loja"><strong>${esc(r.location||'')}</strong></td><td class="col-category" data-label="Categoria">${esc(r.category||'Sem categoria')}</td><td class="col-product" data-label="Produto">${esc(r.product||'')}</td><td class="col-number" data-label="Caixas"><strong>${esc(r.order_qty??'')}</strong></td><td class="col-number" data-label="Unidades">${esc(r.units_total??'')}</td><td class="col-value" data-label="Observações">${esc(r.notes||'')}</td></tr>`).join('');return `<section class="rp-fronts-inline rp-order-inline"><div class="rp-fronts-detail-head"><div><span>Leitura operacional</span><strong>Sugestão de encomenda por loja</strong></div><small>${rows.length} ${rows.length===1?'referência':'referências'}</small></div><div class="rp-fronts-question"><span>Pergunta analisada</span><strong>${esc(m.question_label||m.metric_label||'Sugestão de encomenda')}</strong></div><div class="rp-analytics-fronts-summary">${metricCard('Caixas sugeridas',boxes,'Total do período')}${metricCard('Unidades',units,'Total calculado')}${metricCard('Referências',rows.length,'Com sugestão ou nota')}${metricCard('Lojas',stores,'Com encomenda')}</div><details class="rp-widget-detail" data-analytics-detail><summary><div><span>Dados detalhados</span><strong>Produtos, caixas e observações</strong></div><em>${preview.length} de ${rows.length}</em></summary><div class="rp-widget-detail-body"><div class="rp-table-wrap rp-responsive-analytics-table"><table><thead><tr><th class="col-location">Loja</th><th class="col-category">Categoria</th><th class="col-product">Produto</th><th class="col-number">Caixas</th><th class="col-number">Unidades</th><th class="col-value">Observações</th></tr></thead><tbody>${body||'<tr class="rp-analytics-empty-row"><td colspan="6">Sem sugestões de encomenda no período selecionado.</td></tr>'}</tbody></table></div></div></details></section>`;}
    function frontsInlineHtml(m){
