    }
    function analyticsMetaLabel(value,fallback){const v=String(value||'').trim();if(!v)return fallback||'';const map={latest:'Último valor',sum:'Soma',avg:'Média',count:'Contagem',evidence:'Todas as evidências',submitted_at:'Data da visita',location_id:'Local',route_id:'Rota',project_id:'Campanha',client_id:'Cliente',product_label:'Produto',product:'Produto'};return map[v]||v.replaceAll('_',' ');}
