    function evidencePrepareToken(raw){try{const value=new URL(String(raw||''),location.href).searchParams.get('token')||'';return /^[a-f0-9]{40}$/i.test(value)?value.toLowerCase():'';}catch(_){return'';}}
    function evidenceArchiveAction(m,entity,suffix,label){const files=evidenceFiles(entity?.files);if(!files.length)return '<button type="button" class="rp-evidence-store-action" disabled>Sem imagens</button>';const token=evidencePrepareToken(entity?.download_url);if(!token)return '<button type="button" class="rp-evidence-store-action" disabled title="Atualiza o Analytics para renovar o acesso às evidências">ZIP indisponível</button>';const key=['ev',m.binding_id||m.metric_key||'metric',suffix].join('-').replace(/[^a-z0-9_-]/gi,'-');state.analyticsEvidenceGroups[key]={token,location:entity?.location||entity?.date_label||'evidencias',count:files.length};return `<button type="button" class="rp-evidence-store-action" data-evidence-download="${escAttr(key)}">${esc(label||'Descarregar ZIP')}</button>`;}
    function evidenceIsImage(file){const type=String(file?.type||file?.mime_type||'').toLowerCase(),url=String(file?.url||'').split('?')[0].toLowerCase();return type.indexOf('image/')===0||/\.(jpg|jpeg|png|webp|gif|avif|bmp)$/i.test(url);}
    function evidenceThumbs(files,show=true){if(!show)return'';const valid=evidenceFiles(files);if(!valid.length)return'';return `<div class="rp-evidence-thumbs">${valid.map((f,i)=>{const url=String(f.url||'');const name=String(f.name||('Imagem '+(i+1)));if(url&&evidenceIsImage(f))return `<a class="rp-evidence-thumb" href="${escAttr(url)}" target="_blank" rel="noopener"><img src="${escAttr(url)}" alt="${escAttr(name)}" loading="lazy"><span>${esc(name)}</span></a>`;return url?`<a class="rp-evidence-thumb rp-evidence-file" href="${escAttr(url)}" target="_blank" rel="noopener">${esc(name)}</a>`:`<span class="rp-evidence-thumb rp-evidence-file">${esc(name)}</span>`;}).join('')}</div>`;}
