    function evidenceShellHtml(m,summary,groups){const total=groups.reduce((n,g)=>n+evidenceFiles(g.files).length,0),stores=groups.length,gallery=evidenceGalleryHtml(m,groups);return `<div class="rp-evidence-shell" data-rp-evidence-shell><div class="rp-evidence-toolbar"><div class="rp-evidence-tabs" role="tablist" aria-label="Visualização das evidências"><button type="button" class="rp-evidence-tab is-active" data-rp-evidence-tab="summary" role="tab" aria-selected="true">Resumo</button><button type="button" class="rp-evidence-tab" data-rp-evidence-tab="gallery" role="tab" aria-selected="false">Galeria</button></div><div class="rp-evidence-toolbar-meta"><span class="rp-evidence-pill">${stores} ${stores===1?'loja':'lojas'}</span><span class="rp-evidence-pill">${total} ${total===1?'imagem':'imagens'}</span></div></div><div class="rp-evidence-panel is-active" data-rp-evidence-panel="summary">${summary}</div><div class="rp-evidence-panel" data-rp-evidence-panel="gallery">${gallery}</div></div>`;}
    function evidenceLocationDateHtml(m,groups){const showThumbs=String(m.evidence_show_thumbnails??'1')!=='0';return `<div class="rp-evidence-store-list">${groups.map((g,gi)=>{const files=evidenceFiles(g.files),dates=Array.isArray(g.dates)&&g.dates.length?g.dates:[{date:'',date_label:'Sem data',files,download_url:'',count:files.length}];const storeAction=evidenceArchiveAction(m,{...g,files},`store-${g.location_id||0}-${gi}`,'ZIP da loja');return `<details class="rp-evidence-store-card" data-rp-evidence-store-detail><summary class="rp-evidence-store-head"><div class="rp-evidence-store-copy"><strong>${esc(g.location||('Loja #'+(g.location_id||'')))}</strong><span>${files.length} ${files.length===1?'imagem':'imagens'} · ${dates.length} ${dates.length===1?'data':'datas'}</span></div></summary><div class="rp-evidence-store-body"><div class="rp-evidence-action-row">${storeAction}</div><div class="rp-evidence-date-list">${dates.map((d,di)=>{const dateFiles=evidenceFiles(d.files),action=evidenceArchiveAction(m,{...d,location:(g.location||'Loja')+' · '+(d.date_label||d.date||'Sem data'),files:dateFiles},`date-${g.location_id||0}-${d.date||di}-${di}`,'ZIP da data');return `<details class="rp-evidence-date-group" data-rp-evidence-date-detail><summary class="rp-evidence-date-head"><div><strong>${esc(d.date_label||d.date||'Sem data')}</strong><span>${dateFiles.length} ${dateFiles.length===1?'imagem':'imagens'}${d.route_id?' · Rota #'+esc(d.route_id):(Number(d.route_count||0)>1?' · '+esc(d.route_count)+' rotas':'')}</span></div></summary><div class="rp-evidence-date-body"><div class="rp-evidence-action-row">${action}</div>${evidenceThumbs(dateFiles,showThumbs)}</div></details>`;}).join('')}</div></div></details>`;}).join('')}</div>`;}
