    const totals=routeAggregate(routes);
    if(els.routeListMeta) els.routeListMeta.textContent=routes.length+' rotas · '+range.from+' → '+range.to+' · '+fmtKm(totals.km)+' · '+aggregateMoney(totals.mobility,totals.unresolved);
    if(!routes.length){ els.routeList.innerHTML='<div class="rp-chart-empty">Sem rotas no intervalo De → Até selecionado.</div>'; renderPagination(els.routeListPagination,1,1,()=>{}); return; }
    const perPage=8;
    const view=paginateRows(routes,state.routeListPage,perPage);
    state.routeListPage=view.page;
    const totalsHtml=`<div class="rp-route-list-totals"><div class="rp-route-list-total"><span>Rotas / PDVs</span><strong>${totals.routes} · ${totals.stops} PDVs</strong></div><div class="rp-route-list-total"><span>Km totais</span><strong>${fmtKm(totals.km)}</strong></div><div class="rp-route-list-total"><span>Portagens</span><strong>${aggregateMoney(totals.toll,totals.unresolved)}</strong></div><div class="rp-route-list-total"><span>Combustível / energia</span><strong>${aggregateMoney(totals.energy,totals.unresolved)}</strong></div><div class="rp-route-list-total"><span>Custo operacional</span><strong>${aggregateMoney(totals.operational,totals.unresolved)}</strong></div><div class="rp-route-list-total"><span>Custo deslocação</span><strong>${aggregateMoney(totals.mobility,totals.unresolved)}</strong></div><div class="rp-route-list-total"><span>Âmbito</span><strong>${esc(range.from)} → ${esc(range.to)}</strong></div></div>`;
    const listHtml=view.paged.map(r=>`<button type="button" class="rp-route-item ${String(r.id)===String(state.selectedRouteId)?'active':''}" data-route="${esc(r.id)}"><div class="rp-kicker">${esc(r.date||'')}</div><h4>Rota #${esc(r.id)} · ${fmtKm(routeKm(r))} · ${fmtRouteEur(routeMobilityTotal(r))}</h4><div class="rp-meta">${esc(r.status||'planned')} · ${esc(routeProject(r))} · ${esc(routeOwner(r))} · ${routeStops(r)} PDVs · ${esc(routeIntegrityLabel(r))} · ${esc(routeMobilityLabel(r))}</div></button>`).join('');
    els.routeList.innerHTML=totalsHtml+listHtml;
    renderPagination(els.routeListPagination,view.page,view.total,next=>{ state.routeListPage=next; renderRouteList(); });
    els.routeList.querySelectorAll('[data-route]').forEach(btn=>btn.addEventListener('click',()=>openRouteFromAgenda(btn.dataset.route)));
  }
  function reportBadges(summary){ summary=summary||{}; const items=[]; const add=(value,label,cls='')=>{ const n=parseInt(value||0,10)||0; if(n) items.push(`<span class="rp-report-badge ${cls}">${n} ${esc(label)}</span>`); }; add(summary.answers,'respostas'); add(summary.briefing_questions,'briefing','good'); add(summary.product_rows,'referências','good'); add(summary.zero_products,'ruturas','alert'); add(summary.orders,'encomendas','alert'); add(summary.files,'evidências','file'); if(!items.length) items.push('<span class="rp-report-badge">Sem conteúdo</span>'); return `<div class="rp-report-badges">${items.join('')}</div>`; }
  function reportDetail(presentation){ const p=presentation||{}; const sections=[]; const visit=p.visit||{}; if(visit&&visit.label){ const reason=String(visit.reason||'').trim(); sections.push(`<section class="rp-report-section"><h4>Fecho da visita</h4><div class="rp-report-grid"><div class="rp-report-answer"><strong>${esc(visit.label||'Visita fechada')}</strong><div>${reason?esc(reason):(visit.has_submission?'Submissão operacional associada.':'Sem submissão operacional associada.')}</div><small class="rp-meta">Visita #${esc(visit.id||'')} ${visit.submission_id?' · Submissão #'+esc(visit.submission_id):''}</small></div></div></section>`); } const briefing=Array.isArray(p.briefing_questions)?p.briefing_questions:[]; if(briefing.length){ sections.push(`<section class="rp-report-section"><h4>Briefing da loja</h4><div class="rp-meta">Apenas perguntas mapeadas para esta loja e para o âmbito do operativo selecionado.</div><div class="rp-report-grid">${briefing.map(q=>`<div class="rp-report-answer"><strong>${esc(q.label||'Pergunta de briefing')}</strong><div>${q.answered?esc(q.answer||'0'):'Sem resposta'}</div><small class="rp-meta">${esc(q.briefing_title||'Briefing')}</small></div>`).join('')}</div></section>`); }
    const answers=Array.isArray(p.answers)?p.answers:[]; if(answers.length){ sections.push(`<section class="rp-report-section"><h4>Respostas do formulário</h4><div class="rp-report-grid">${answers.map(a=>{const rv=a.value;const isStruct=typeof rv==='string'&&/^[\[{]/.test(rv.trim());return `<div class="rp-report-answer"><strong>${esc(a.label||'Resposta')}</strong><div>${isStruct?'Resposta estruturada, ver detalhe completo':esc(rv||'')}</div></div>`;}).join('')}</div></section>`); }
    (Array.isArray(p.product_questions)?p.product_questions:[]).forEach(q=>{ const cats=Array.isArray(q.categories)?q.categories:[]; if(!cats.length) return; const rows=Array.isArray(q.rows)?q.rows:[]; const zero=rows.filter(x=>String(x.status||'')==='zero').length; const positive=rows.filter(x=>String(x.status||'')==='positive').length; const changed=rows.filter(x=>!!x.changed).length; const blocks=cats.map(cat=>`<details class="rp-report-category"><summary>${esc(cat.name||'Sem categoria')} · ${parseInt(cat.count||0,10)||0} referências · ${parseInt(cat.zero||0,10)||0} a zero</summary><table class="rp-report-mini"><thead><tr><th>Referência</th><th>Produto</th><th>Valor</th><th>Estado</th></tr></thead><tbody>${(Array.isArray(cat.rows)?cat.rows:[]).map(prod=>{ const before=String(prod.before??''); const after=String(prod.after??''); const value=(before!==''||after!=='')?[before,after].filter(v=>v!=='').join(' → '):String(prod.value??prod.qty??''); const isZero=String(prod.status||'')==='zero'; const status=isZero?'Rutura / zero':(String(prod.status||'')==='positive'?'Com presença':'Sem classificação'); return `<tr><td>${esc(prod.ref||'')}</td><td>${esc(prod.name||'Produto')}</td><td class="${isZero?'rp-report-zero':''}">${esc(value||'Sem valor')}</td><td>${esc(status)}${prod.changed?' · Alterado':''}</td></tr>`; }).join('')}</tbody></table></details>`).join(''); sections.push(`<section class="rp-report-section"><h4>${esc(q.label||'Produtos')}</h4><div class="rp-meta">${rows.length} referências · ${zero} ruturas · ${positive} com presença${changed?` · ${changed} alterações`:''}</div>${blocks}</section>`); });
    (Array.isArray(p.order_questions)?p.order_questions:[]).forEach(q=>{ const cats=Array.isArray(q.categories)?q.categories:[]; if(!cats.length) return; const blocks=cats.map(cat=>`<details class="rp-report-category"><summary>${esc(cat.name||'Sem categoria')} · ${parseInt(cat.count||0,10)||0} referências · ${esc(cat.boxes??0)} caixas</summary><table class="rp-report-mini"><thead><tr><th>Referência</th><th>Produto</th><th>Caixas</th><th>Unidades</th><th>Observações</th></tr></thead><tbody>${(Array.isArray(cat.rows)?cat.rows:[]).map(order=>`<tr><td>${esc(order.ref||'')}</td><td>${esc(order.name||'Produto')}</td><td>${esc(order.order_qty??'')}</td><td>${esc(order.units_total??'')}</td><td>${esc(order.notes||'')}</td></tr>`).join('')}</tbody></table></details>`).join(''); sections.push(`<section class="rp-report-section"><h4>${esc(q.label||'Sugestão de encomenda')}</h4><div class="rp-meta">Apenas referências com quantidade ou observação.</div>${blocks}</section>`); });
    const files=Array.isArray(p.files)?p.files:[]; if(files.length){ sections.push(`<section class="rp-report-section"><h4>Evidências e ficheiros</h4><div class="rp-report-badges">${files.map(file=>`<a class="rp-small" href="${escAttr(file.url||'#')}" target="_blank" rel="noopener">${esc(file.label||'Abrir ficheiro')}</a>`).join('')}</div></section>`); }
    return sections.join('')||'<div class="rp-chart-empty">Esta submissão não tem respostas preenchidas.</div>'; }
