  function paramsForReports(){ const p=new URLSearchParams(); if(els.client&&els.client.value) p.set('client_id',els.client.value); if(els.project&&els.project.value) p.set('project_id',els.project.value); if(els.owner&&els.owner.value) p.set('owner_user_id',els.owner.value); if(els.location&&els.location.value) p.set('location_id',els.location.value); if(els.from&&els.from.value) p.set('date_from',els.from.value); if(els.to&&els.to.value) p.set('date_to',els.to.value); /* Reports obey only the canonical header scope. A route opened in Rotas must never leak into Relatórios. */ p.set('report_mode','visits'); return p; }
