  function buildAdminPostExportUrl(params,action,nonceValue,format){ const p=new URLSearchParams(params instanceof URLSearchParams?params.toString():''); p.set('action',action); p.set('_wpnonce',nonceValue||''); p.set('format',format); return exportAdminUrl+'?'+p.toString(); }
  function exportUrl(format){ return buildAdminPostExportUrl(paramsForReports(),'routespro_export_submissions',exportNonce,format); }
  function dashboardExportUrl(format){ const p=paramsForStats(); const scope=analyticsHeaderDateScope(); if(scope.from)p.set('from',scope.from); else p.delete('from'); if(scope.to)p.set('to',scope.to); else p.delete('to'); return buildAdminPostExportUrl(p,'routespro_export_dashboard',dashboardExportNonce,format); }
  function routeExportUrl(format){ const p=new URLSearchParams(); if(els.client&&els.client.value) p.set('client_id',els.client.value); if(els.project&&els.project.value) p.set('project_id',els.project.value); if(els.owner&&els.owner.value) p.set('owner_user_id',els.owner.value); if(els.from&&els.from.value) p.set('date_from',els.from.value); if(els.to&&els.to.value) p.set('date_to',els.to.value); return buildAdminPostExportUrl(p,'routespro_export_routes',routeExportNonce,format); }
  function safeRefreshExportLinks(){ try{ refreshExportLinks(); return true; }catch(err){ if(window.console&&typeof window.console.error==='function') console.error('[FieldFlow] Export runtime link refresh failed',err); return false; } }
  // 9D4: visits are fetched by canonical server-side pages, never silently
  // truncated to the old 1000-row browser snapshot. Sequence + scope checks
  // prevent slow requests from replacing a newer client/date selection.
  let reportLoadSequence=0;
  // Backwards-compatible entrypoint; server paging is delegated to loadReportsPage.
  async function loadReports(){ return loadReportsPage(1); }
  async function loadReportsPage(page=1){
    if(!els.reportTable) return;
    const currentPage=Math.max(1,parseInt(page||1,10)||1);
    const scoped=paramsForReports();
    const scopeSignature=scoped.toString();
    const requestSequence=++reportLoadSequence;
    scoped.set('limit','10');
    scoped.set('offset',String((currentPage-1)*10));
    scoped.set('with_total','1');
    if(els.reportsMeta) els.reportsMeta.textContent='A carregar relatórios...';
    try{
      const data=await j(api+'form-submissions?'+scoped.toString());
      if(requestSequence!==reportLoadSequence||paramsForReports().toString()!==scopeSignature)return;
      const rows=Array.isArray(data?.rows)?data.rows:[];
      state.reports={rows,columns:Array.isArray(data?.columns)?data.columns:[],total:Number(data?.total??rows.length),page:currentPage};
      renderReports(currentPage);
      safeRefreshExportLinks();
    }catch(err){
      if(requestSequence!==reportLoadSequence||paramsForReports().toString()!==scopeSignature)return;
      state.reports={rows:[],columns:[],total:0,page:currentPage};
      renderReports(currentPage);
      if(els.reportsMeta) els.reportsMeta.textContent='Falha ao carregar relatórios';
      throw err;
    }
  }
  function renderReports(page=1){ const cols=['Data','Loja e rota','Formulário','Operativo','Conteúdo']; if(els.reportHead) els.reportHead.innerHTML='<tr>'+cols.map(label=>`<th>${esc(label)}</th>`).join('')+'</tr>'; const rows=Array.isArray(state.reports.rows)?state.reports.rows:[]; if(els.reportsMeta) els.reportsMeta.textContent=(state.reports.total||rows.length||0)+' visitas fechadas'; const current=state.reports||{}; const perPage=10; const currentPage=Math.max(1,parseInt(current.page||page,10)||1); const totalPages=Math.max(1,Math.ceil((Number(current.total)||0)/perPage)); const view={page:currentPage,total:totalPages,paged:rows}; if(!view.paged.length){ els.reportTable.innerHTML='<tr><td colspan="5">Sem visitas fechadas para os filtros atuais.</td></tr>'; renderPagination(els.reportsPagination,1,1,()=>{}); return; } els.reportTable.innerHTML=view.paged.map(r=>{ const p=r.presentation||{}; const visit=p.visit||{}; const date=esc(r.report_day||r.route_date||r.submitted_at||''); const location=esc(r.location_name||'Sem loja'); const route=`Rota #${esc(r.route_id||r.joined_route_id||0)} · Paragem #${esc(r.route_stop_id||r.stop_row_id||0)}`; const form=esc(r.form_title||((r.form_id||0)?`Formulário #${r.form_id}`:'Sem formulário associado')); const scope=[r.client_name,r.project_name].filter(Boolean).map(esc).join(' · '); const owner=esc(r.owner_name||'Sem operativo'); const submitter=esc(r.user_name||''); const preview=esc(p.preview||''); const visitId=esc(r.route_stop_id||r.stop_row_id||r.report_id||''); const subLabel=r.submission_id?`Submissão #${esc(r.submission_id)}`:'Sem submissão'; return `<tr class="rp-report-main"><td><strong>Visita #${visitId}</strong><div class="rp-meta">${date}<br>${subLabel}</div><div style="margin-top:5px">${badge(visit.label||r.status||'closed')}</div></td><td><strong>${location}</strong><div class="rp-meta">${route}<br>${esc(r.stop_status||'')}</div></td><td><strong>${form}</strong><div class="rp-meta">${scope}</div></td><td><strong>${owner}</strong><div class="rp-meta">${submitter}</div></td><td>${reportBadges(p.summary||{})}<div class="rp-meta">${preview}</div></td></tr><tr class="rp-report-detail"><td colspan="5"><details><summary>Ver reporte completo</summary><div class="rp-report-body">${reportDetail(p)}</div></details></td></tr>`; }).join(''); renderPagination(els.reportsPagination,view.page,view.total,next=>loadReportsPage(next).catch(err=>setStatus(err.message||'Falha ao carregar relatórios.'))); }

  function renderRouteDetail(){ const route=state.selectedRoute; if(!route){ els.routeDetail.innerHTML='<div class="rp-chart-empty">Seleciona uma rota para ver e editar o detalhe.</div>'; return; } const stops=Array.isArray(route.stops)?route.stops:[]; const metrics=routeMetrics(route); const mobility=routeMobility(route); const statusOptions=['planned','draft','in_progress','completed','canceled']; const currentStatus=String(route.status||'planned')==='done'?'completed':(String(route.status||'planned')==='cancelled'?'canceled':String(route.status||'planned')); const doneCount=stops.filter(s=>['done','completed'].includes(String(s.status||'').toLowerCase())).length; const failedCount=stops.filter(s=>String(s.status||'').toLowerCase()==='failed').length; const coordsCount=stops.filter(s=>Number.isFinite(parseFloat(s.lat))&&Number.isFinite(parseFloat(s.lng))).length; const pendingCount=Math.max(0, stops.length-doneCount-failedCount); const doneRate=stops.length?Math.round((doneCount/stops.length)*100):0; els.routeDetail.innerHTML=`<div class="rp-panel-head" style="margin-bottom:8px"><div><h3 style="font-size:22px">Rota #${esc(route.id)}</h3><p>Data ${esc(route.date||'')} · ${esc(statusLabel(route.status||'planned'))} · ${stops.length} paragens</p></div><span class="rp-pill">Editor rápido</span></div><div class="rp-kpi-grid" style="margin-bottom:14px">${metricCard('Paragens',stops.length,'Total carregado')}${metricCard('Concluídas',doneCount,'Paragens concluídas')}${metricCard('Pendentes',pendingCount,'Ainda por executar')}${metricCard('% rota',doneRate+'%','Execução atual da rota')}${metricCard('Falhadas',failedCount,'Paragens com falha operacional')}${metricCard('Com coordenadas',coordsCount,'Pontos prontos para navegação')}${metricCard('Km totais',fmtKm(routeKm(route)),routeIntegrityLabel(route))}${metricCard('Acesso',fmtKm(metrics.access_distance_km),'Partida até ao primeiro PDV')}${metricCard('Entre PDVs',fmtKm(metrics.inter_stop_distance_km),'Percurso operacional')}${metricCard('Regresso',fmtKm(metrics.return_distance_km),'Último PDV até à chegada')}${metricCard('Viagem',metrics.travel_min!=null?Math.round(parseFloat(metrics.travel_min)||0)+' min':'Por calcular','Tempo total em estrada')}${metricCard('Poupança',fmtKm(metrics.optimization_saved_distance_km||0),(metrics.optimization_saved_travel_min||0)+' min poupados')}${metricCard('Direção',esc(metrics.territory_dominant_direction_label||'Por calcular'),(metrics.territory_dominant_share_pct||0)+'% das visitas')}${metricCard('Coerência',esc(metrics.territory_coherence_label||'Por calcular'),(metrics.territory_locality_reentries||0)+' regressos a localidades')}${metricCard('Arco territorial',esc((metrics.territory_bearing_span_deg||0)+'°'),esc(metrics.territory_route_cone_label||'Por calcular'))}${metricCard('Fonte',esc(routeSourceLabel(route)),'Matriz e cálculo canónicos')}${metricCard('Portagens',fmtRouteEur(routeToll(route)),routeMobilityLabel(route))}${metricCard('Combustível / energia',Number(mobility.enabled||0)===1?fmtRouteEur(routeEnergyCost(route)):'Não configurado',routeMobilityLabel(route))}${metricCard('Custo operacional',Number(mobility.enabled||0)===1?fmtRouteEur(routeOperationalCost(route)):'Não configurado','Viatura, manutenção e custo por km · '+routeMobilityLabel(route))}${metricCard('Litros / kWh',Number(mobility.enabled||0)===1?((routeMobilityQuantity(route,'estimated_litres')==null&&routeMobilityQuantity(route,'estimated_kwh')==null)?'Por calcular':((routeMobilityQuantity(route,'estimated_litres')||0).toLocaleString('pt-PT',{maximumFractionDigits:2})+' L · '+(routeMobilityQuantity(route,'estimated_kwh')||0).toLocaleString('pt-PT',{maximumFractionDigits:2})+' kWh')):'--',routeMobilityLabel(route))}${metricCard('Custo deslocação total',fmtRouteEur(routeMobilityTotal(route)),'Energia + custo operacional + portagens · '+routeMobilityLabel(route))}${metricCard('Estado',esc(statusLabel(route.status||'planned')),'Estado atual da rota')}</div><div class="rp-row" style="display:flex;gap:10px;flex-wrap:wrap;align-items:center"><select id="rpcp-route-status">${statusOptions.map(s=>`<option value="${s}" ${currentStatus===s?'selected':''}>${esc(statusLabel(s))}</option>`).join('')}</select><button type="button" class="rp-small primary" id="rpcp-save-route-status">Atualizar estado</button><button type="button" class="rp-small alt" id="rpcp-open-route-maps">Abrir no Maps</button><button type="button" class="rp-small" id="rpcp-reload-route">Recarregar rota</button></div><div class="rp-stop-list">${stops.map((stop,idx)=>`<div class="rp-stop" data-stop="${stop.id}"><div class="rp-stop-no">${idx+1}</div><div><h4 style="margin:0 0 6px">${esc(stop.location_name||'PDV')}</h4><div class="rp-meta">${esc(stop.address||'')}</div><div style="margin-top:8px">${badge(stop.status||'pending')}</div><div class="rp-stop-actions"><button type="button" class="rp-small" data-move="up" data-stop="${stop.id}" aria-label="Subir paragem">▲</button><button type="button" class="rp-small" data-move="down" data-stop="${stop.id}" aria-label="Descer paragem">▼</button><button type="button" class="rp-small primary" data-stop-status="done" data-stop="${stop.id}">Concluir</button><button type="button" class="rp-small" data-stop-status="pending" data-stop="${stop.id}">Pendente</button></div></div></div>`).join('') || '<div class="rp-chart-empty">Sem paragens nesta rota.</div>'}</div>`;
    const moveStop=(stopId,direction)=>{ const arr=route.stops||[]; const idx=arr.findIndex(s=>String(s.id)===String(stopId)); if(idx<0) return; const swap=direction==='up'?idx-1:idx+1; if(swap<0||swap>=arr.length) return; const temp=arr[idx]; arr[idx]=arr[swap]; arr[swap]=temp; arr.forEach((s,i)=>{ s.seq=i+1; }); renderRouteDetail(); renderReports(); };
    els.routeDetail.querySelector('#rpcp-save-route-status')?.addEventListener('click', async()=>{ try{ await j(api+'routes/'+route.id,{method:'PATCH',headers:{'Content-Type':'application/json','X-WP-Nonce':nonce},body:JSON.stringify({status:els.routeDetail.querySelector('#rpcp-route-status').value})}); setStatus('Estado da rota atualizado.'); await selectRoute(route.id,false); await loadPortal(false); }catch(err){ setStatus(err.message||'Falha ao atualizar rota.'); } });
    els.routeDetail.querySelector('#rpcp-open-route-maps')?.addEventListener('click', ()=>{ const url=String(route.google_maps_url||'').trim(); if(!url){ return setStatus('Esta rota ainda não tem pontos válidos para abrir no Google Maps.'); } if(window.FieldFlowNavigation&&typeof window.FieldFlowNavigation.open==='function'){window.FieldFlowNavigation.open(url,{source:'client_route_detail'});}else{window.location.assign(url);} });
    els.routeDetail.querySelector('#rpcp-reload-route')?.addEventListener('click', ()=>selectRoute(route.id,true));
    els.routeDetail.querySelectorAll('[data-move]').forEach(btn=>btn.addEventListener('click', ()=>moveStop(btn.dataset.stop,btn.dataset.move)));
    els.routeDetail.querySelectorAll('[data-stop-status]').forEach(btn=>btn.addEventListener('click', async()=>{ try{ await j(api+'stops/'+btn.dataset.stop,{method:'PATCH',headers:{'Content-Type':'application/json','X-WP-Nonce':nonce},body:JSON.stringify({status:btn.dataset.stopStatus})}); setStatus('Estado da paragem atualizado.'); await selectRoute(route.id,false); await loadPortal(false); }catch(err){ setStatus(err.message||'Falha ao atualizar paragem.'); } }));
    const persistSequence=async()=>{ if(!canManage || !Array.isArray(route.stops)) return; for(let i=0;i<route.stops.length;i++){ const stop=route.stops[i]; await j(api+'stops/'+stop.id,{method:'PATCH',headers:{'Content-Type':'application/json','X-WP-Nonce':nonce},body:JSON.stringify({seq:i+1})}); } setStatus('Ordem das paragens gravada.'); };
    els.routeDetail.querySelectorAll('[data-move]').forEach(btn=>btn.addEventListener('click', ()=>setTimeout(()=>persistSequence().catch(err=>setStatus(err.message||'Falha ao gravar ordem.')),40)));
  }
  async function selectRoute(routeId, announce, lockDate){ if(!routeId){ state.selectedRouteId=0; state.selectedRoute=null; renderRouteCalendar(); renderOwnerRoutesSummary(); renderRouteList(); renderRouteDetail(); await loadReports(); return; } try{ state.selectedRouteId=parseInt(routeId,10)||0; const cached=(state.routeAgenda||state.routes||[]).find(r=>String(r.id)===String(routeId)); if(lockDate && cached && cached.date) setRouteDateLock(String(cached.date), cached.id); state.selectedRoute=await j(api+'routes/'+routeId); renderRouteCalendar(); renderOwnerRoutesSummary(); renderRouteList(); renderRouteDetail(); await loadReports(); if(announce) setStatus('Rota carregada com sucesso.'); }catch(err){ setStatus(err.message||'Falha ao carregar detalhe da rota.'); } }
  function activePanelKey(){ return root.querySelector('.rp-panel.active')?.dataset.panel||'overview'; }
  async function ensurePanelData(key,refresh=false){
    key=String(key||'overview');
    if(!refresh && state.panelLoads[key]) return;
    state.panelLoads[key]=true;
    try{
      if(key==='campaign-pdvs') await loadCampaignPdvs(false);
      if(key==='reports' && !state.selectedRouteId) await loadReports();
      if(key==='analytics') await loadClientAI(refresh);
    }catch(err){ state.panelLoads[key]=false; setStatus(err.message||'Falha ao carregar o módulo.'); }
  }
  async function loadPortal(withStatus=true){ try{ if(withStatus) setStatus('A atualizar portal...'); state.panelLoads={}; const [stats,commercial]=await Promise.all([j(api+'stats?'+paramsForStats().toString()).catch(()=>({by_day:[]})), j(api+'commercial-search?'+paramsForCommercial().toString()).catch(()=>({stats:{}}))]); state.stats=stats||{}; state.commercial=commercial||{}; renderKpis(state.stats); renderCommercialKpis(state.commercial); renderChart(state.stats.by_day||[]); renderRoutesTable(state.stats.by_day||[]); renderAnalytics(state.stats); ensurePortalTableScroll(); await loadRoutesRange(); await ensurePanelData(activePanelKey(),true); safeRefreshExportLinks(); enforcePortalScopeLocks(); lockCommercialPanel(); if(withStatus) setStatus('Portal atualizado.'); }catch(err){ setStatus(err.message||'Falha ao atualizar portal.'); } }
  root.querySelectorAll('.rp-tabbar button[data-panel]').forEach(btn=>{btn.setAttribute('role','tab');btn.addEventListener('click',()=>switchPanel(btn.dataset.panel||'overview'));});
  root.querySelector('.rp-tabbar')?.setAttribute('role','tablist');
  switchPanel(activePanelKey(),{remember:false,announce:false});
  root.querySelector('#rpcp-refresh')?.addEventListener('click',()=>loadPortal(true));
  if(els.aiRefresh) els.aiRefresh.addEventListener('click',()=>loadClientAI(true));
  function bindCampaignButtons(){
    const refresh=root.querySelector('#rpcp-campaign-refresh');
    const save=root.querySelector('#rpcp-campaign-save');
    if(refresh && !refresh.dataset.bound){ refresh.dataset.bound='1'; refresh.addEventListener('click',ev=>{ ev.preventDefault(); ev.stopPropagation(); state.campaign.page=1; loadCampaignPdvs(true); }); }
    if(save && !save.dataset.bound){ save.dataset.bound='1'; save.addEventListener('click',ev=>{ ev.preventDefault(); ev.stopPropagation(); saveCampaignPdvs(false); }); }
  }
  bindCampaignButtons();
  root.addEventListener('click',ev=>{
    const refresh=ev.target.closest('#rpcp-campaign-refresh');
    const save=ev.target.closest('#rpcp-campaign-save');
    if(refresh && root.contains(refresh)){ ev.preventDefault(); ev.stopPropagation(); state.campaign.page=1; loadCampaignPdvs(true); return; }
    if(save && root.contains(save)){ ev.preventDefault(); ev.stopPropagation(); saveCampaignPdvs(false); return; }
  }, true);
  [els.campaignQ,els.campaignStatus,els.campaignActive,els.campaignOwner,els.campaignPerPage].forEach(el=>{ if(!el) return; const ev=el.tagName==='SELECT'?'change':'input'; let t=null; el.addEventListener(ev,()=>{ clearTimeout(t); t=setTimeout(()=>{ if(el===els.campaignPerPage) state.campaign.perPage=parseInt(el.value||'25',10)||25; state.campaign.page=1; loadCampaignPdvs(true); }, el.tagName==='SELECT'?0:350); }); });
  if(els.client){ els.client.addEventListener('change',async()=>{ setRouteDateLock('',0); state.selectedRouteId=0; state.selectedRoute=null; state.ownerRoutesPage=1; state.routeListPage=1; state.campaign.page=1; syncProjects(); applyCampaignTheme(); await syncOwners(); await syncLocations(); enforcePortalScopeLocks(); const detail={portal:'client',client_id:els.client.value||'',project_id:els.project?.value||'',owner_user_id:els.owner?.value||'',location_id:els.location?.value||''}; root.querySelectorAll('.rp-front-commercial').forEach(fc=>fc.dispatchEvent(new CustomEvent('routespro:scope-change',{detail}))); document.dispatchEvent(new CustomEvent('routespro:scope-change',{detail})); loadPortal(true); }); }
  if(els.project){ syncProjects(); els.project.addEventListener('change',async()=>{ setRouteDateLock('',0); state.selectedRouteId=0; state.selectedRoute=null; state.ownerRoutesPage=1; state.routeListPage=1; state.campaign.page=1; applyCampaignTheme(); await syncOwners(); await syncLocations(); const detail={portal:'client',client_id:els.client?.value||'',project_id:els.project.value||'',owner_user_id:els.owner?.value||'',location_id:els.location?.value||''}; root.querySelectorAll('.rp-front-commercial').forEach(fc=>fc.dispatchEvent(new CustomEvent('routespro:scope-change',{detail}))); document.dispatchEvent(new CustomEvent('routespro:scope-change',{detail})); enforcePortalScopeLocks(); loadPortal(true); }); }
  if(els.owner) els.owner.addEventListener('change',async()=>{ setRouteDateLock('',0); state.selectedRouteId=0; state.selectedRoute=null; state.ownerRoutesPage=1; state.routeListPage=1; state.campaign.page=1; await syncLocations(); loadPortal(true); });
  if(els.location) els.location.addEventListener('change',()=>{ syncLocationSearchText(); renderLocationOptions(); state.selectedRouteId=0; state.selectedRoute=null; state.routeListPage=1; loadPortal(true); });
  if(els.locationSearch){ els.locationSearch.addEventListener('focus',()=>openLocationPicker(true)); els.locationSearch.addEventListener('click',()=>openLocationPicker(true)); els.locationSearch.addEventListener('input',()=>{ renderLocationOptions(); openLocationPicker(true); if(String(els.locationSearch.value||'').trim()==='' && els.location&&els.location.value){ clearLocation(false); } }); els.locationSearch.addEventListener('keydown',ev=>{ if(ev.key==='Enter'){ ev.preventDefault(); selectLocationFromText(els.locationSearch.value); } else if(ev.key==='Escape'){ openLocationPicker(false); syncLocationSearchText(); } else if(ev.key==='ArrowDown'){ ev.preventDefault(); openLocationPicker(true); const first=els.locationOptions?.querySelector('.rp-search-option'); if(first) first.focus(); } }); window.addEventListener('resize',placeLocationPicker); window.addEventListener('scroll',()=>{ if(els.locationPicker?.classList.contains('open')) placeLocationPicker(); }, true); }
  if(els.locationOptions){ els.locationOptions.addEventListener('mousedown',ev=>{ ev.preventDefault(); const btn=ev.target.closest('.rp-search-option'); if(!btn) return; const val=btn.dataset.value||''; if(!val){ clearLocation(); openLocationPicker(false); return; } const opt=locationOptions().find(o=>String(o.value)===String(val)); chooseLocation(val, opt?opt.text:btn.textContent); }); els.locationOptions.addEventListener('keydown',ev=>{ const btn=ev.target.closest('.rp-search-option'); if(!btn) return; if(ev.key==='Enter'||ev.key===' '){ ev.preventDefault(); btn.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true})); } else if(ev.key==='Escape'){ openLocationPicker(false); els.locationSearch?.focus(); } }); }
  if(els.locationClear){ els.locationClear.addEventListener('click',ev=>{ ev.preventDefault(); clearLocation(); openLocationPicker(false); }); }
  document.addEventListener('click',ev=>{ if(els.locationPicker && !els.locationPicker.contains(ev.target)) openLocationPicker(false); });
  if(els.from){ els.from.addEventListener('input',syncAnalyticsExportDateAuthority); els.from.addEventListener('change',async()=>{ syncAnalyticsExportDateAuthority(); state.selectedRouteId=0; state.selectedRoute=null; state.routeListPage=1; state.campaign.page=1; setRouteDateLock('',0); await syncLocations(); loadPortal(true); }); }
  if(els.to){ els.to.addEventListener('input',syncAnalyticsExportDateAuthority); els.to.addEventListener('change',async()=>{ syncAnalyticsExportDateAuthority(); state.selectedRouteId=0; state.selectedRoute=null; state.routeListPage=1; state.campaign.page=1; setRouteDateLock('',0); await syncLocations(); loadPortal(true); }); }
  function refreshExportLinks(){
    const map=[[els.exportCsv,'csv','reports'],[els.exportCsvDetail,'csv_detail','reports'],[els.exportXls,'xlsx','reports'],[els.exportXlsMobile,'xlsx_mobile','reports'],[els.exportPdf,'pdf','reports'],[els.analyticsExportCsv,'csv','analytics'],[els.analyticsExportXls,'xlsx','analytics'],[els.analyticsExportXlsMobile,'xlsx_mobile','analytics'],[els.analyticsExportPdf,'pdf','analytics'],[els.routeExportCsv,'csv','routes'],[els.routeExportXls,'xls','routes'],[els.routeExportPdf,'pdf','routes']];
    if(els.routeExportScope){ const selected=els.owner&&els.owner.value?String(els.owner.options[els.owner.selectedIndex]?.text||'Operativo'):'Todas as rotas'; els.routeExportScope.textContent=els.owner&&els.owner.value?'Rotas · '+selected:'Todas as rotas'; }
    map.forEach(([btn,format,type])=>{
      if(!btn) return;
      const disabled=type==='analytics'?!dashboardExportNonce:(type==='routes'?!routeExportNonce:!exportNonce);
      btn.setAttribute('aria-disabled', disabled ? 'true' : 'false');
      btn.style.opacity=disabled?'0.55':'1';
      btn.style.pointerEvents=disabled?'none':'auto';
      btn.style.cursor=disabled?'not-allowed':'pointer';
      btn.style.position='relative';
      btn.style.zIndex='9999';
      btn.style.filter='none';
      btn.style.visibility='visible';
      const formatLabel=format==='csv_detail'?'CSV dados':format.toUpperCase();
      const exportLabel=type==='analytics'?'analytics':(type==='routes'?'rotas':'relatório');
      btn.title=disabled?'Sessão expirada para exportação. Atualiza a página.':'Exportar '+exportLabel+' em '+formatLabel;
      const href=disabled?'#':(type==='analytics'?dashboardExportUrl(format):(type==='routes'?routeExportUrl(format):exportUrl(format)));
      btn.setAttribute('href',href);
      btn.removeAttribute('target');
      btn.setAttribute('rel','noopener');
    });
  }
  [els.exportCsv, els.exportCsvDetail, els.exportXls, els.exportXlsMobile, els.exportPdf, els.analyticsExportCsv, els.analyticsExportXls, els.analyticsExportXlsMobile, els.analyticsExportPdf, els.routeExportCsv, els.routeExportXls, els.routeExportPdf].forEach(btn=>{
    if(!btn) return;
    if([els.analyticsExportCsv,els.analyticsExportXls,els.analyticsExportXlsMobile,els.analyticsExportPdf].includes(btn)){btn.addEventListener('pointerdown',syncAnalyticsExportDateAuthority,{passive:true});btn.addEventListener('touchstart',syncAnalyticsExportDateAuthority,{passive:true});}
    btn.addEventListener('click', function(ev){
      safeRefreshExportLinks();
      if(btn.getAttribute('href')==='#'){
        ev.preventDefault();
        setStatus('Sessão expirada para exportação. Atualiza a página.');
      }
    });
  });
  enforcePortalScopeLocks();
  applyCampaignTheme();
  await syncOwners();
  await syncLocations();
  lockCommercialPanel();
  await loadPortal(false);
  ensurePortalTableScroll();
})();
</script>
